using UnityEngine;
using Flynn.Events;

// 2.5D force-based character controller. Moves on the XZ plane via acceleration
// toward a target velocity, so Unity physics drives interactions: PhysicMaterial
// friction (ice/mud), Rigidbody.drag (water), and AddForce zones (wind) all
// compose naturally instead of being overwritten. Small jump impulse, gravity
// handled by the Rigidbody.
[RequireComponent(typeof(Rigidbody))]
public class SolarpunkCharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;        // target horizontal speed under input
    [SerializeField] private float acceleration = 40f;    // how hard we drive toward target
    [SerializeField] private float jumpForce = 6f;
    // Baseline drag is 0: accel-to-target already arrests horizontal motion when input is
    // released (target velocity 0 -> decel force), so we need no passive drag — and drag is
    // isotropic, which would damp jump/fall. Water zones raise this temporarily; ice keeps it low.
    [SerializeField] private float groundDrag = 0f;
    [SerializeField] private float groundCheckDistance = 0.12f;
    [SerializeField] private LayerMask groundLayers = ~0;
    // Ice low-grip is re-asserted by the zone every physics step. Latch it for a short grace
    // window so a single missed OnTriggerStay (e.g. player center crossing the trigger edge
    // while the capsule is still on the ice) doesn't snap the ground brake back on for a step
    // and bleed the slide. Grace ends well before the player is truly off the ice.
    [SerializeField] private float lowGripGrace = 0.2f;

    public Vector3 MoveInput => moveInput;
    public bool IsGrounded => isGrounded;
    /// <summary>Horizontal speed normalized 0-1 relative to moveSpeed.</summary>
    public float NormalizedSpeed => rb != null
        ? Mathf.Clamp01(new Vector2(rb.velocity.x, rb.velocity.z).magnitude / moveSpeed)
        : 0f;

    /// <summary>Multiplies steering force each physics step. Ice sets this low (slidey, weak
    /// steering, momentum dominates) — kept &gt;0 so the player can always escape ice. Auto-resets to 1.</summary>
    public float SteeringControl { get; set; } = 1f;

    /// <summary>Multiplies the target move speed each physics step. Water/Mud set this below 1 to
    /// slow the player noticeably (lowering the target, since drag/friction barely dents accel-to-target).
    /// Auto-resets to 1.</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>Set false each physics step by a mud zone while grounded on it: blocks jumping
    /// ("mud stops vertical movement"). Auto-resets to true.</summary>
    public bool CanJump { get; set; } = true;

    /// <summary>Set true each physics step by an ice zone: the controller stops braking toward
    /// zero when there's no input, so momentum carries (glide). Steering still applies (scaled by
    /// SteeringControl) so the player can nudge off the ice. Auto-resets to false.</summary>
    public bool LowGrip { get; set; } = false;

    /// <summary>Set false to block horizontal movement (e.g. during a swing attack).
    /// Auto-resets to true each physics step so you only need to hold it false while swinging.</summary>
    public bool CanMove { get; set; } = true;

    public Vector3 RbVelocityDirection { get; private set; }

    private Rigidbody rb;
    private Collider bodyCollider;
    private bool isGrounded;
    private bool wasGrounded;
    private Vector3 moveInput;
    private bool jumpQueued;
    private float lowGripTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = CanMove ? new Vector3(moveInput.x, 0f, moveInput.z) : Vector3.zero;
        bool idle = inputDir.sqrMagnitude < 0.01f;
        if (!CanMove)
        {
            // Kill horizontal velocity immediately when movement is locked
            Vector3 v = rb.velocity;
            v.x = 0f;
            v.z = 0f;
            rb.velocity = v;
        }
        else
        {
            // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
            // The brake stays off for the whole grace window, surviving single-step trigger gaps.
            if (LowGrip) lowGripTimer = lowGripGrace;
            else lowGripTimer -= Time.fixedDeltaTime;
            bool lowGrip = lowGripTimer > 0f;
            if (lowGrip)
            {
                // Ice: momentum carries, input only steers. With input, push in the input direction
                // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
                // ground), so existing momentum is preserved and the velocity vector rotates toward
                // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
                // force can't run away. Idle = no force, the frictionless surface keeps the glide.
                if (!idle)
                {
                    rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                    Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                    float maxSpeed = moveSpeed * SpeedMultiplier;
                    if (hv.magnitude > maxSpeed)
                    {
                        hv = hv.normalized * maxSpeed;
                        rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                    }
                }
            }
            else
            {
                // Normal ground: accelerate toward the input-driven target velocity (XZ only).
                Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
                Vector3 dv = targetVel - horizVel;
                rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
            }
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
            PublishEvent(new PlayerJumped(transform.position));
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        CanMove = true;
        LowGrip = false;

        // Detect landing (was airborne, now grounded).
        if (!wasGrounded && isGrounded)
            PublishEvent(new PlayerLanded(transform.position));
        wasGrounded = isGrounded;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        // Ground check ray
        if (bodyCollider != null)
        {
            Vector3 origin = bodyCollider.bounds.center;
            origin.y = bodyCollider.bounds.min.y + 0.02f;
            Debug.DrawLine(origin, origin + Vector3.down * groundCheckDistance,
                isGrounded ? Color.green : Color.red);
        }

        // Velocity vector
        if (rb != null)
        {
            Debug.DrawRay(transform.position, rb.velocity, Color.cyan);
        }
    }
#endif
}

using UnityEngine;

/// <summary>
/// Drives the procedural cube character rig (twin-stick). Replaces the sprite-sheet
/// <see cref="FlynnAnimationDriver"/> on the cube player while satisfying the same
/// <see cref="IPlayerVisual"/> contract, so wrench/throw/rope/reticle keep working.
///
/// Rig layout (assigned in the Inspector):
///   BodyRig  — yaws to follow the mouse aim point (torso + arms).
///   LegRig   — yaws to the movement direction when moving, blends back to body when idle.
///   FootL/R  — translated in an opposite-phase step cycle along LegRig's local forward.
///   ArmR     — pitched back on charge, swept forward on release (procedural swing pose).
///
/// Decoupling BodyRig (→ mouse) from LegRig (→ move) is what produces the twin-stick look:
/// the torso aims while the legs walk in the direction you actually travel.
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class ProceduralCharacterDriver : MonoBehaviour, IPlayerVisual
{
    [Header("Sources")]
    [SerializeField] private SolarpunkCharacterController _controller;

    [Header("Rig")]
    [Tooltip("Torso pivot. Yaws to face the mouse aim point. Holds the body cube + arms.")]
    [SerializeField] private Transform _bodyRig;
    [Tooltip("Leg pivot. Yaws to the movement direction; blends to body facing when idle.")]
    [SerializeField] private Transform _legRig;
    [SerializeField] private Transform _footL;
    [SerializeField] private Transform _footR;
    [Tooltip("Right arm, swept procedurally during a swing.")]
    [SerializeField] private Transform _armR;
    [Tooltip("Hand position used as the throw/rope origin (VisualCenter). Falls back to body centre.")]
    [SerializeField] private Transform _handSocket;

    [Header("Facing")]
    [Tooltip("Rest / idle facing in world space (default -Z = toward the camera / screen-down).")]
    [SerializeField] private Vector3 _restForward = Vector3.back;
    [Tooltip("How far the body turns toward the movement heading off the rest facing. " +
             "1 = face the move direction fully (up = away from camera); " +
             "lower softens it (0.5 → pure left/right leans ~45°). Idle always returns to rest.")]
    [SerializeField, Range(0f, 1f)] private float _leanFactor = 1f;
    [Tooltip("How fast the body/legs slerp toward their target facing (per second).")]
    [SerializeField] private float _turnSpeed = 14f;

    [Header("Step cycle")]
    [Tooltip("Stride length: how far each foot travels fore/aft from neutral (world units).")]
    [SerializeField] private float _stride = 0.12f;
    [Tooltip("Foot lift height at the top of a step (world units).")]
    [SerializeField] private float _stepLift = 0.06f;
    [Tooltip("Step cycles per second at full speed.")]
    [SerializeField] private float _stepFrequency = 2.2f;

    [Header("Visual centre")]
    [Tooltip("Used only when no hand socket is assigned: body-centre height above the root.")]
    [SerializeField] private float _visualHalfHeight = 0.4f;

    [Header("Swing pose")]
    [Tooltip("Arm pitch (deg, local X) at full windup charge.")]
    [SerializeField] private float _windupAngle = -70f;
    [Tooltip("Arm pitch (deg, local X) at the forward end of a swing.")]
    [SerializeField] private float _swingThroughAngle = 60f;
    [Tooltip("Seconds the release sweep takes.")]
    [SerializeField] private float _swingDuration = 0.25f;

    private const float MoveEpsilon = 0.05f;

    private enum SwingPhase { None, Charging, Releasing }
    private SwingPhase _swingPhase = SwingPhase.None;
    private float _chargePitch;       // current windup pitch while charging
    private float _swingTimer;        // counts down through the release sweep
    private Quaternion _armRest = Quaternion.identity;

    private Vector3 _footLRest;
    private Vector3 _footRRest;
    private float _stepPhase;
    private float _stepWeight;        // 0 idle → 1 moving, smoothed so feet settle

    // ── IPlayerVisual ───────────────────────────────────────────────────────────

    public Vector3 VisualCenter =>
        _handSocket != null ? _handSocket.position
                            : transform.position + Vector3.up * _visualHalfHeight;

    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    public bool IsAttacking => _swingPhase != SwingPhase.None;

    public void TriggerAttack(int animIndex)
    {
        // No charge: snap straight into a release sweep.
        if (_swingPhase == SwingPhase.None) ReleaseSwing(animIndex, 1f);
    }

    public void BeginChargePose(int animIndex)
    {
        _swingPhase = SwingPhase.Charging;
        _chargePitch = 0f;
    }

    public void UpdateChargePose(int animIndex, float charge01)
    {
        if (_swingPhase != SwingPhase.Charging) return;
        _chargePitch = Mathf.Lerp(0f, _windupAngle, Mathf.Clamp01(charge01));
    }

    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        _swingPhase = SwingPhase.Releasing;
        // Higher animSpeed → shorter sweep (faster follow-through).
        _swingTimer = _swingDuration / Mathf.Max(0.05f, animSpeed);
    }

    public void CancelSwing()
    {
        _swingPhase = SwingPhase.None;
        _swingTimer = 0f;
        _chargePitch = 0f;
    }

    public void BeginSwingWindup() { }
    public void CancelSwingWindup() { CancelSwing(); }
    public void TriggerSwing() { TriggerAttack(4); }

    public void FaceWorldDirection(Vector3 worldDir)
    {
        // No-op: facing is fully movement-driven (lean-to-move). Kept for the IPlayerVisual
        // contract — the wrench/rope controllers still call it, but it must not fight the lean.
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private float _restYaw;

    private void Awake()
    {
        if (_controller == null) _controller = GetComponent<SolarpunkCharacterController>();
        Vector3 rest = _restForward; rest.y = 0f;
        if (rest.sqrMagnitude < 0.0001f) rest = Vector3.back;
        _restYaw = Quaternion.LookRotation(rest.normalized, Vector3.up).eulerAngles.y;
        if (_footL != null) _footLRest = _footL.localPosition;
        if (_footR != null) _footRRest = _footR.localPosition;
        if (_armR != null) _armRest = _armR.localRotation;
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        UpdateBodyFacing(dt);
        UpdateLegFacing(dt);
        UpdateStepCycle(dt);
        UpdateSwingPose(dt);
    }

    // ── Rig logic ───────────────────────────────────────────────────────────────

    private void UpdateBodyFacing(float dt)
    {
        if (_bodyRig == null) return;

        Vector3 move = _controller.MoveInput;
        move.y = 0f;

        // Turn toward the movement heading in all directions (up = facing away from camera).
        // _leanFactor scales how much of the rest→move angular delta is applied; 1 = face the
        // move direction fully. Idle → rest facing.
        float targetYaw = _restYaw;
        if (move.sqrMagnitude > MoveEpsilon * MoveEpsilon)
        {
            float moveYaw = Quaternion.LookRotation(move.normalized, Vector3.up).eulerAngles.y;
            targetYaw = _restYaw + Mathf.DeltaAngle(_restYaw, moveYaw) * _leanFactor;
        }

        Quaternion target = Quaternion.Euler(0f, targetYaw, 0f);
        _bodyRig.rotation = Quaternion.Slerp(_bodyRig.rotation, target, _turnSpeed * dt);
    }

    private void UpdateLegFacing(float dt)
    {
        // Legs share the body facing; the step cycle runs along that shared forward.
        if (_legRig != null && _bodyRig != null) _legRig.rotation = _bodyRig.rotation;
    }

    private void UpdateStepCycle(float dt)
    {
        float speed01 = Mathf.Clamp01(_controller != null ? _controller.NormalizedSpeed : 0f);
        bool moving = speed01 > 0.05f;

        // Ease the step amplitude in/out so feet settle cleanly when stopping.
        _stepWeight = Mathf.MoveTowards(_stepWeight, moving ? 1f : 0f, dt * 6f);
        if (moving) _stepPhase += dt * _stepFrequency * Mathf.Lerp(0.4f, 1f, speed01) * Mathf.PI * 2f;

        float s = Mathf.Sin(_stepPhase) * _stepWeight;
        ApplyFoot(_footL, _footLRest, s);
        ApplyFoot(_footR, _footRRest, -s);
    }

    private void ApplyFoot(Transform foot, Vector3 rest, float phase)
    {
        if (foot == null) return;
        // phase ∈ [-1,1]: fore/aft along local Z, lift only on the forward (positive) half.
        foot.localPosition = rest
            + Vector3.forward * (phase * _stride)
            + Vector3.up * (Mathf.Max(0f, phase) * _stepLift);
    }

    private void UpdateSwingPose(float dt)
    {
        if (_armR == null) return;

        float pitch;
        switch (_swingPhase)
        {
            case SwingPhase.Charging:
                pitch = _chargePitch;
                break;
            case SwingPhase.Releasing:
                _swingTimer -= dt;
                float t = _swingDuration > 0f
                    ? 1f - Mathf.Clamp01(_swingTimer / (_swingDuration))
                    : 1f;
                // Sweep from the windup angle through to the follow-through angle.
                pitch = Mathf.Lerp(_windupAngle, _swingThroughAngle, t);
                if (_swingTimer <= 0f) _swingPhase = SwingPhase.None;
                break;
            default:
                pitch = 0f;
                break;
        }

        Quaternion target = _armRest * Quaternion.Euler(pitch, 0f, 0f);
        // Snap while actively swinging, ease back to rest when idle.
        _armR.localRotation = _swingPhase == SwingPhase.None
            ? Quaternion.Slerp(_armR.localRotation, target, 12f * dt)
            : target;
    }
}

using UnityEngine;

/// <summary>
/// Reads SolarpunkCharacterController state and feeds the Animator on the Visual child.
/// 8-direction facing driven by FacingDir (float): 0=Down, 1=DownLeft, 2=Left,
/// 3=UpLeft, 4=Up, 5=UpRight, 6=Right, 7=DownRight.
/// Right-side facing uses explicit sprites (no flip needed for 8-dir run).
/// Non-run animations map diagonals to nearest cardinal and flip when needed.
/// Camera-relative: "Down" = toward the camera.
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class FlynnAnimationDriver : MonoBehaviour, IPlayerVisual
{
    [SerializeField] private SolarpunkCharacterController _controller;
    [SerializeField] private Camera _camera;
    [Tooltip("The child Visual GameObject that holds the SpriteRenderer + Animator.")]
    [SerializeField] private Transform _visualRoot;
    [SerializeField, Range(0.1f, 5f)] private float _visualScale = 1f;

    [Header("Run speed scaling")]
    [Tooltip("Movement speed that maps to 1× animation speed.")]
    [SerializeField] private float _runSpeedBase = 5f;

    [Header("Facing (sprite flip)")]
    [Tooltip("SpriteRenderer to flip. Auto-found on _visualRoot at Awake if left empty.")]
    [SerializeField] private SpriteRenderer _sprite;
    [Tooltip("Min horizontal speed before facing updates.")]
    [SerializeField, Range(0f, 1f)] private float _faceDeadzone = 0.05f;

    [Header("Visual Center (for throw origin & aim reticle)")]
    [Tooltip("Half the sprite's visible height in world units. Used to compute the billboard's visual centre for camera-corrected spawn/reticle positions.")]
    [SerializeField, Range(0f, 3f)] private float _spriteHalfHeight = 0.5f;

    [Header("Normal Maps")]
    [Tooltip("Material whose _BumpMap will be swapped at runtime.")]
    [SerializeField] private Material _spriteMaterial;
    [Tooltip("Normal map for idle / non-run states.")]
    [SerializeField] private Texture _idleNormal;
    [Tooltip("Normal map for the run state.")]
    [SerializeField] private Texture _runNormal;
    [Tooltip("Normal map for the swing state.")]
    [SerializeField] private Texture _swingNormal;

    // ── Cached references ──────────────────────────────────────────────────────

    private Animator _animator;

    // Held while idle so the blend tree doesn't snap back to Down on release.
    private int _lastFacingDir;
    private bool _lastFlipX;
    private string _lastStateName;

    // Locked while swinging to prevent Update() from overwriting FacingDir.
    private bool _swingFacingLocked;

    // ── Animator parameter hashes ─────────────────────────────────────────────

    private static readonly int SpeedHash       = Animator.StringToHash("Speed");
    private static readonly int IsGroundedHash  = Animator.StringToHash("IsGrounded");
    private static readonly int JumpHash        = Animator.StringToHash("Jump");
    private static readonly int SwingHash       = Animator.StringToHash("Swing");
    private static readonly int SwingWindupHash = Animator.StringToHash("SwingWindup");
    private static readonly int SwingChargingHash = Animator.StringToHash("SwingCharging");
    private static readonly int HoldHash        = Animator.StringToHash("Hold");
    private static readonly int ThrowHash       = Animator.StringToHash("Throw");
    private static readonly int ScanHash        = Animator.StringToHash("Scan");
    private static readonly int FacingDirHash   = Animator.StringToHash("FacingDir");

    // ── IPlayerVisual ─────────────────────────────────────────────────────────

    public Vector3 VisualCenter =>
        _visualRoot != null
            ? _visualRoot.position + _visualRoot.up * _spriteHalfHeight
            : transform.position;

    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    public bool IsAttacking =>
        _animator != null &&
        (IsInSwingState(_animator.GetCurrentAnimatorStateInfo(0)) ||
         (_animator.IsInTransition(0) &&
          IsInSwingState(_animator.GetNextAnimatorStateInfo(0))));

    private bool IsInSwingState(AnimatorStateInfo info) =>
        StateNameStartsWith(info, "Swing") || StateNameStartsWith(info, "SwingWindup") || StateNameStartsWith(info, "SwingRelease");

    public void TriggerAttack(int animIndex)
    {
        // Legacy tool-index attack stubbed — use TriggerSwing instead.
    }

    public void BeginChargePose(int animIndex)
    {
        // Legacy charge windup stubbed.
    }

    public void UpdateChargePose(int animIndex, float charge01)
    {
        // Legacy charge scrub stubbed.
    }

    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        if (_animator == null) return;
        _animator.SetBool(SwingChargingHash, false);
        // SwingCharging IfNot triggers SwingWindup→SwingRelease transition.
        // For quick taps not in windup, fire Swing trigger to reach Swing_* directly.
        if (!StateNameStartsWith(_animator.GetCurrentAnimatorStateInfo(0), "SwingWindup"))
            _animator.SetTrigger(SwingHash);
    }

    public void BeginSwingWindup()
    {
        if (_animator == null) return;
        _swingFacingLocked = true;
        _animator.SetBool(SwingChargingHash, true);
        _animator.SetTrigger(SwingWindupHash);
    }

    public void CancelSwingWindup()
    {
        if (_animator == null) return;
        _swingFacingLocked = false;
        _animator.SetBool(SwingChargingHash, false);
    }

    public void CancelSwing()
    {
        if (_animator == null) return;
        _swingFacingLocked = false;
        _animator.SetBool(SwingChargingHash, false);
        _animator.Play("Idle", 0, 0f);
    }

    /// <summary>
    /// Sets FacingDir from a world-space direction (e.g. player→mouse aim point).
    /// Used by WrenchSwingController to make the swing face where the player clicks.
    /// </summary>
    public void FaceWorldDirection(Vector3 worldDir)
    {
        if (_animator == null || _camera == null) return;

        int dir = WorldDirectionToFacingDir(worldDir);
        _animator.SetInteger(FacingDirHash, dir);
        _lastFacingDir = dir;
        _lastFlipX = false;
        if (_sprite != null) _sprite.flipX = false;
    }

    /// <summary>
    /// Converts a world-space direction vector into an 8-sector FacingDir (0–7)
    /// using the same camera-relative sector logic as the locomotion Update.
    /// </summary>
    private int WorldDirectionToFacingDir(Vector3 worldDir)
    {
        Vector3 camFwd   = Vector3.ProjectOnPlane(_camera.transform.forward, Vector3.up).normalized;
        Vector3 camRight = Vector3.ProjectOnPlane(_camera.transform.right, Vector3.up).normalized;

        float intoScreen  = Vector3.Dot(worldDir, camFwd);
        float screenRight = Vector3.Dot(worldDir, camRight);

        float angle = Mathf.Atan2(-screenRight, -intoScreen) * Mathf.Rad2Deg;
        if (angle < 0f) angle += 360f;

        bool flip = angle > 180f;
        if (flip) angle = 360f - angle;

        int dir;
        if      (angle < 22.5f)  dir = 0;
        else if (angle < 67.5f)  dir = 1;
        else if (angle < 112.5f) dir = 2;
        else if (angle < 157.5f) dir = 3;
        else                     dir = 4;

        if (flip)
        {
            dir = dir switch
            {
                1 => 7,
                2 => 6,
                3 => 5,
                _ => dir
            };
        }

        return dir;
    }

    // ── Frame-by-frame trigger API ────────────────────────────────────────────

    public void TriggerJump()
    {
        Debug.Log($"[Anim] Jump (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(JumpHash);
    }

    public void TriggerSwing()
    {
        if (_animator == null) return;
        _animator.SetBool(SwingChargingHash, false);
        _animator.SetTrigger(SwingHash);
    }

    public void SetHolding(bool holding)
    {
        Debug.Log($"[Anim] Hold = {holding} (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetBool(HoldHash, holding);
    }

    public void TriggerThrow()
    {
        Debug.Log($"[Anim] Throw (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(ThrowHash);
    }

    public void TriggerScan()
    {
        Debug.Log($"[Anim] Scan (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(ScanHash);
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        // Get Animator from the Visual child (not self)
        if (_visualRoot != null)
        {
            _animator = _visualRoot.GetComponent<Animator>();
            if (_sprite == null) _sprite = _visualRoot.GetComponentInChildren<SpriteRenderer>();
            _visualRoot.localScale = Vector3.one * _visualScale;
        }
        if (_camera == null) _camera = Camera.main;
        Debug.Log($"[Anim] Awake — visualRoot={(_visualRoot != null ? _visualRoot.name : "NULL")}, animator={(_animator != null ? "ok" : "NULL")}, sprite={(_sprite != null ? _sprite.name : "NULL")}");
    }

    private void Update()
    {
        if (_animator == null || _controller == null) return;

        Vector3 velocity = _controller.MoveInput;
        Vector2 xz = new Vector2(velocity.x, velocity.z);

        // Feed Speed and IsGrounded for locomotion
        _animator.SetFloat(SpeedHash, xz.magnitude);
        _animator.SetBool(IsGroundedHash, _controller.IsGrounded);

        // ── Camera-relative facing direction ──────────────────────────────────
        // Down = toward camera, Up = away from camera, Left = screen-left
        if (!_swingFacingLocked)
        {
            if (_camera != null && xz.sqrMagnitude >= _faceDeadzone * _faceDeadzone)
            {
                int dir = WorldDirectionToFacingDir(velocity);

                _animator.SetInteger(FacingDirHash, dir);
                if (_sprite != null) _sprite.flipX = false;

                _lastFacingDir = dir;
                _lastFlipX = false;
            }
            else
            {
                // Hold last facing when idle
                _animator.SetInteger(FacingDirHash, _lastFacingDir);
                if (_sprite != null) _sprite.flipX = _lastFlipX;
            }
        }

        // Unlock facing once the swing chain finishes
        if (_swingFacingLocked && !IsAttacking)
            _swingFacingLocked = false;

        // ── Scale Run animation speed by actual horizontal velocity ────────────
        var stateInfo = _animator.GetCurrentAnimatorStateInfo(0);
        if (StateNameStartsWith(stateInfo, "Run"))
        {
            var rb = _controller.GetComponent<Rigidbody>();
            float hSpeed = rb != null
                ? new Vector2(rb.velocity.x, rb.velocity.z).magnitude
                : xz.magnitude;
            _animator.speed = Mathf.Max(hSpeed / _runSpeedBase, 0.25f);
        }
        else if (StateNameStartsWith(stateInfo, "SwingWindup"))
        {
            // Play the windup slowly through its frames without looping
            _animator.speed = 0.3f;
        }
        else
        {
            _animator.speed = 1f;
        }

        // ── Swap normal map based on current state ─────────────────────────────
        SwapNormalMap(stateInfo);
    }

    // ── Normal map swapping ───────────────────────────────────────────────────

    private void SwapNormalMap(AnimatorStateInfo stateInfo)
    {
        if (_spriteMaterial == null) return;

        string stateName = null;
        if (StateNameStartsWith(stateInfo, "Run")) stateName = "Run";
        else if (StateNameStartsWith(stateInfo, "Swing") || StateNameStartsWith(stateInfo, "SwingWindup") || StateNameStartsWith(stateInfo, "SwingRelease")) stateName = "Swing";
        else if (StateNameStartsWith(stateInfo, "Idle")) stateName = "Idle";

        if (stateName == _lastStateName) return;
        _lastStateName = stateName;

        Texture normal;
        if (stateName == "Run") normal = _runNormal;
        else if (stateName == "Swing") normal = _swingNormal;
        else normal = _idleNormal;

        if (normal != null)
            _spriteMaterial.SetTexture("_NormalMap", normal);
    }

    /// <summary>
    /// Checks if the current animator state name starts with the given prefix.
    /// Needed because 8-dir states are named "Idle_Down", "Run_UpLeft", etc.
    /// </summary>
    private bool StateNameStartsWith(AnimatorStateInfo stateInfo, string prefix)
    {
        string[] dirSuffixes = { "_Down", "_DownLeft", "_Left", "_UpLeft", "_Up", "_UpRight", "_Right", "_DownRight" };
        foreach (var suffix in dirSuffixes)
        {
            if (stateInfo.IsName(prefix + suffix))
                return true;
        }
        // Also check bare name (e.g. "Idle", "Run") for legacy/blend-tree compatibility
        if (stateInfo.IsName(prefix))
            return true;
        return false;
    }
}

using UnityEngine;

/// <summary>
/// The visual/animation surface the player's combat &amp; interaction controllers drive,
/// decoupled from how the body is actually rendered. Implemented by both the legacy
/// sprite-sheet driver (<see cref="FlynnAnimationDriver"/>) and the procedural cube-rig
/// driver (<see cref="ProceduralCharacterDriver"/>) so the same wrench/throw/rope/reticle
/// logic works against either body without edits.
///
/// Controllers resolve it via <c>GetComponent&lt;IPlayerVisual&gt;()</c> in Awake.
/// </summary>
public interface IPlayerVisual
{
    /// <summary>World-space "hand" / chest origin for thrown projectiles and the rope end.</summary>
    Vector3 VisualCenter { get; }

    /// <summary>VisualCenter projected to the character's foot Y (ground-plane indicators).</summary>
    Vector3 VisualGroundCenter { get; }

    /// <summary>True while an attack/swing is playing (gates re-triggering).</summary>
    bool IsAttacking { get; }

    /// <summary>Fire the attack pose for the given tool index (1=pick 2=axe 3=hammer 4=wrench).</summary>
    void TriggerAttack(int animIndex);

    /// <summary>Enter the windup hold for the given tool index.</summary>
    void BeginChargePose(int animIndex);

    /// <summary>Scrub the windup pose with charge fraction 0→1 (also live-swaps the tool).</summary>
    void UpdateChargePose(int animIndex, float charge01);

    /// <summary>Release the swing at the given playback speed (higher = faster follow-through).</summary>
    void ReleaseSwing(int animIndex, float animSpeed);

    /// <summary>Enter the looping windup animation (first half of swing) while charging.</summary>
    void BeginSwingWindup();

    /// <summary>Cancel the windup animation and return to idle.</summary>
    void CancelSwingWindup();

    /// <summary>Fire the swing directly without windup (quick tap).</summary>
    void TriggerSwing();

    /// <summary>Abort a windup and return to neutral.</summary>
    void CancelSwing();

    /// <summary>Orient the body toward a world-space XZ direction. Ignores Y; no-op on zero.</summary>
    void FaceWorldDirection(Vector3 worldDir);
}

using UnityEngine;

/// <summary>
/// Single-responsibility component that owns all mouse → world target detection. Every interaction
/// reads what's under the cursor from here; nothing keeps its own proximity registry.
///
/// It no longer casts its own rays: <see cref="MousePointer"/> does ONE cursor raycast per frame
/// (against its combined world mask) and this component derives every hovered target from that one
/// shared hit. The object under the cursor is resolved once; each concern asks it for the component
/// it cares about and applies its own range gate. Consequence of the single union cast: the closest
/// object under the cursor wins across all layers (uniform occlusion) — there are no per-concern
/// masks that can see a target through something in front of it.
///
/// Other systems read the public properties; this component only ever reads — it writes nothing.
/// Requires a <see cref="MousePointer"/> in the scene whose mask covers ground + resources + pickups
/// + grapple + melee surfaces (the union of what used to be per-concern masks here).
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class PlayerMouseAimer : MonoBehaviour
{
    [SerializeField] private float _maxAimDistance = 30f;

    /// <summary>Max distance from the player to a resource or pickup for it to count as interactable.</summary>
    [SerializeField] private float _interactionRange = 3f;

    /// <summary>Public access to the interaction range for other controllers.</summary>
    public float InteractionRange => _interactionRange;

    [Tooltip("Max distance from the player to a melee surface for a wrench swing to register its tool/hit.")]
    [SerializeField] private float _meleeRange = 2.5f;

    private MousePointer _pointer;

    // ── Public properties ─────────────────────────────────────────────────────

    /// <summary>World-space position the mouse cursor is pointing at.</summary>
    public Vector3 WorldAimPoint { get; private set; }

    /// <summary>
    /// The ResourceNode the mouse ray is pointing at, or null.
    /// Only set when the hit node is within <see cref="_interactionRange"/> of the player.
    /// </summary>
    public ResourceNode HoveredResource { get; private set; }

    /// <summary>
    /// The WorldItemPickup the mouse ray is pointing at, or null. (Legacy; new world objects use
    /// <see cref="WorldItem"/> / <see cref="HoveredKeyPickup"/>.) Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItemPickup HoveredPickup { get; private set; }

    /// <summary>
    /// The non-auto-collect <see cref="WorldItem"/> under the cursor (e.g. the wrench), or null.
    /// These require the pickup key — auto-collecting items magnet themselves and never appear here.
    /// Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItem HoveredKeyPickup { get; private set; }

    /// <summary>The RopeAnchor the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopeAnchor HoveredAnchor { get; private set; }

    /// <summary>The RopePullable the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopePullable HoveredPullable { get; private set; }

    /// <summary>Exact world surface point hit on the current grapple target. Valid only when an anchor or pullable is hovered.</summary>
    public Vector3 HoveredGrapplePoint { get; private set; }

    /// <summary>
    /// Animator AttackIndex of the surface under the cursor within <see cref="_meleeRange"/>.
    /// Defaults to 4 (wrench / "air") when nothing meleeable is in reach. The wrench swing
    /// reads this to decide which tool to transform into.
    /// </summary>
    public int SwingAnimIndex { get; private set; } = 4;

    /// <summary>
    /// The ResourceNode under the cursor within melee reach, or null. Used by the swing to
    /// apply harvest damage. Non-resource surfaces (HittableSurface) drive the tool anim but
    /// leave this null (no damage).
    /// </summary>
    public ResourceNode MeleeResource { get; private set; }

    /// <summary>
    /// The interaction-prompt provider the player is currently targeting (pickup, grapple point,
    /// NPC, …), or null. Generic — the HUD reads this and renders whatever prompt it returns.
    /// </summary>
    public IInteractionPromptProvider HoveredInteractable { get; private set; }

    /// <summary>The GameObject the mouse ray is pointing at (from MousePointer), or null.</summary>
    public GameObject HoveredGameObject
    {
        get
        {
            if (_pointer == null) _pointer = MousePointer.Instance;
            return _pointer != null ? _pointer.HoverObject : null;
        }
    }

    /// <summary>
    /// Unified hover result produced each frame. All consumers should read from this
    /// instead of the individual HoveredXxx properties (which are deprecated).
    /// </summary>
    public PlayerAimHoverResult HoverResult { get; private set; }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Update()
    {
        if (_pointer == null) _pointer = MousePointer.Instance;
        if (_pointer == null) return;

        GameObject hovered = _pointer.HoverObject;
        bool hasHit = _pointer.HasHit;
        Vector3 point = _pointer.WorldPoint;

        UpdateAimPoint(hasHit, point);
        UpdateHoveredResource(hovered);
        UpdateHoveredPickup(hovered);
        UpdateHoveredKeyPickup(hovered);
        UpdateHoveredGrapple(hovered, point);
        UpdateHoveredGrabbable(hovered);
        UpdateMeleeTarget(hovered, hasHit, point);
        UpdateHoveredInteractable(hovered, hasHit, point);

        // Build unified hover result
        BuildHoverResult(hasHit, point, hovered);
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void UpdateAimPoint(bool hasHit, Vector3 point)
    {
        if (hasHit)
        {
            WorldAimPoint = point;
            return;
        }
        // Miss: intersect the horizontal plane at this object's Y so aim still resolves over open ground.
        var plane = new Plane(Vector3.up, new Vector3(0f, transform.position.y, 0f));
        if (plane.Raycast(_pointer.WorldRay, out float dist))
            WorldAimPoint = _pointer.WorldRay.GetPoint(Mathf.Min(dist, _maxAimDistance));
    }

    private void UpdateHoveredResource(GameObject hovered)
    {
        ResourceNode node = Find<ResourceNode>(hovered);
        HoveredResource = node != null && WithinInteractionRange(node.transform.position) ? node : null;
    }

    private void UpdateHoveredPickup(GameObject hovered)
    {
        WorldItemPickup pickup = Find<WorldItemPickup>(hovered);
        HoveredPickup = pickup != null && WithinInteractionRange(pickup.transform.position) ? pickup : null;
    }

    private void UpdateHoveredKeyPickup(GameObject hovered)
    {
        WorldItem item = Find<WorldItem>(hovered);
        // Only key-pickup items (e.g. the wrench) surface here; auto-collect items magnet themselves.
        bool needsKey = item != null && item.Item != null && !item.Item.AutoCollects;
        HoveredKeyPickup = needsKey && WithinInteractionRange(item.transform.position) ? item : null;
    }

    private void UpdateHoveredGrapple(GameObject hovered, Vector3 point)
    {
        // Whichever marker the hovered object carries decides the kind; range is left to the
        // controller (RopeLassoConfig owns it). Anchor and pullable are mutually exclusive.
        RopeAnchor anchor = Find<RopeAnchor>(hovered);
        if (anchor != null)
        {
            HoveredAnchor = anchor;
            HoveredPullable = null;
            HoveredGrapplePoint = point;
            return;
        }

        RopePullable pullable = Find<RopePullable>(hovered);
        HoveredAnchor = null;
        HoveredPullable = pullable;
        if (pullable != null) HoveredGrapplePoint = point;
    }

    private void UpdateMeleeTarget(GameObject hovered, bool hasHit, Vector3 point)
    {
        // ResourceNode wins (it carries damage + its own tool); otherwise a HittableSurface decides
        // the tool; nothing in reach = wrench (air).
        MeleeResource = null;
        SwingAnimIndex = 4;
        if (!hasHit || hovered == null) return;
        if (Vector3.Distance(transform.position, point) > _meleeRange) return;

        ResourceNode node = Find<ResourceNode>(hovered);
        if (node != null)
        {
            MeleeResource = node;
            SwingAnimIndex = node.AttackAnimIndex;
            return;
        }

        HittableSurface surface = Find<HittableSurface>(hovered);
        if (surface != null)
            SwingAnimIndex = surface.AttackAnimIndex;
    }

    private void UpdateHoveredInteractable(GameObject hovered, bool hasHit, Vector3 point)
    {
        HoveredInteractable = null;

        // 1) Generic interaction target within reach — pickups, NPCs, inspectables, etc.
        if (hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange)
        {
            var provider = hovered.GetComponentInParent<IInteractionPromptProvider>();
            if (provider != null) { HoveredInteractable = provider; return; }
        }

        // 2) Fall back to the rope-lasso targets (their reach is owned by the lasso controller,
        //    so they prompt even past the generic interaction range).
        if (HoveredAnchor is IInteractionPromptProvider anchor)        HoveredInteractable = anchor;
        else if (HoveredPullable is IInteractionPromptProvider pull)   HoveredInteractable = pull;
    }

    private void UpdateHoveredGrabbable(GameObject hovered)
    {
        HoveredGrabbable = null;
        if (hovered == null) return;

        Grabbable g = hovered.GetComponentInParent<Grabbable>();
        if (g == null) return;

        // Range gate: must be within interaction range (or already held)
        if (g.IsHeld || Vector3.Distance(transform.position, g.transform.position) <= _interactionRange)
            HoveredGrabbable = g;
    }

    /// <summary>The Grabbable object the mouse ray is pointing at, or null.</summary>
    public Grabbable HoveredGrabbable { get; private set; }

    /// <summary>Component of type T on the hovered object or its parents, or null.</summary>
    private static T Find<T>(GameObject hovered) where T : Component
        => hovered != null ? hovered.GetComponentInParent<T>() : null;

    private bool WithinInteractionRange(Vector3 worldPos)
        => Vector3.Distance(transform.position, worldPos) <= _interactionRange;

    private void BuildHoverResult(bool hasHit, Vector3 point, GameObject hovered)
    {
        HoverResult = new PlayerAimHoverResult
        {
            HasTarget = hasHit || HoveredAnchor != null || HoveredPullable != null || HoveredGrabbable != null,
            WorldPoint = WorldAimPoint,
            WorldItem = HoveredKeyPickup,
            ResourceNode = HoveredResource,
            MeleeResource = MeleeResource,
            RopeAnchor = HoveredAnchor,
            RopePullable = HoveredPullable,
            ScanTarget = hovered != null ? Find<ScanTarget>(hovered) : null,
            Interactable = HoveredInteractable,
            Grabbable = HoveredGrabbable,
            GrapplePoint = HoveredGrapplePoint,
            InInteractionRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange,
            InMeleeRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _meleeRange,
            SwingAnimIndex = SwingAnimIndex,
        };
    }
}

using UnityEngine;

/// <summary>
/// Applies a momentum lean to a billboarded 2D sprite visual by adding X/Z euler
/// rotation after the Billboard component sets the camera-facing rotation.
/// Y rotation is never touched — Billboard owns that. Runs after Billboard via
/// DefaultExecutionOrder. Position is offset so the lean pivots from the feet.
/// </summary>
[DefaultExecutionOrder(100)]
public class VelocityLeanDriver : MonoBehaviour
{
    [SerializeField] private SolarpunkCharacterController _controller;
    [SerializeField] private float _maxLeanDeg = 12f;
    [SerializeField] private float _leanSpeed = 8f;
    [Tooltip("Vertical distance from transform origin down to feet for pivot offset.")]
    [SerializeField] private float _footOffsetY = 0.455f;

    private float _currentLeanX;
    private float _currentLeanZ;
    private float _targetLeanX;
    private float _targetLeanZ;
    private Vector3 _baseLocalPos;

    private void Awake()
    {
        _baseLocalPos = transform.localPosition;
    }

    private void LateUpdate()
    {
        if (_controller == null) return;

        // Use MoveInput direction + NormalizedSpeed so lean is responsive
        // even when Rigidbody velocity gets zeroed by the controller between frames
        var input = _controller.MoveInput;
        var speed = _controller.NormalizedSpeed; // 0-1

        if (speed > 0.05f && input.sqrMagnitude > 0.001f)
        {
            // Normalize the XZ input for direction
            var dir = new Vector3(input.x, 0f, input.z).normalized;
            // Moving +Z → lean forward (positive X rotation)
            // Moving +X → lean right (negative Z rotation)
            _targetLeanX = dir.z * speed * _maxLeanDeg;
            _targetLeanZ = -dir.x * speed * _maxLeanDeg;
        }
        else
        {
            _targetLeanX = 0f;
            _targetLeanZ = 0f;
        }

        _currentLeanX = Mathf.Lerp(_currentLeanX, _targetLeanX, _leanSpeed * Time.deltaTime);
        _currentLeanZ = Mathf.Lerp(_currentLeanZ, _targetLeanZ, _leanSpeed * Time.deltaTime);

        // Add lean to Billboard's rotation (X and Z only, Y preserved)
        var euler = transform.eulerAngles;
        euler.x += _currentLeanX;
        euler.z += _currentLeanZ;
        transform.eulerAngles = euler;

        // Offset position so lean pivots from feet instead of center
        var leanRot = Quaternion.Euler(_currentLeanX, 0f, _currentLeanZ);
        Vector3 feetOffset = new Vector3(0f, -_footOffsetY, 0f);
        transform.localPosition = _baseLocalPos + leanRot * feetOffset - feetOffset;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Player startup script. Owns the player's wiring to the <see cref="ResourceManager"/>:
/// it subscribes to resource events on startup and is the publisher that raises player hits
/// via <see cref="EmitHit"/>. Also supports the new <see cref="ToolHitContext"/>-based
/// hit flow that routes through <see cref="ResourceNode.TryApplyToolHit"/> with tool
/// effectiveness lookups.
/// </summary>
public class PlayerInitializer : MonoBehaviour
{
    [Header("Debug")]
    [Tooltip("Press to raise a test hit at the player's position (verifies the event pipe). None = disabled.")]
    [SerializeField] private KeyCode _debugHitKey = KeyCode.None;

    private void OnEnable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit += HandleResourceHit;
    }

    private void OnDisable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit -= HandleResourceHit;
    }

    private void Update()
    {
        if (_debugHitKey != KeyCode.None && Input.GetKeyDown(_debugHitKey))
            EmitHit(transform.position, null, 1);
    }

    /// <summary>Publisher: raise a player hit through the manager (legacy PlayerHitInfo path).</summary>
    public void EmitHit(Vector3 point, GameObject target = null, int power = 1)
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.RaiseHit(new PlayerHitInfo(point, target, power));
    }

    /// <summary>
    /// Publisher: raise a tool hit with full context. Routes through the effectiveness
    /// system by finding the <see cref="ResourceNode"/> on the target and calling
    /// <see cref="ResourceNode.TryApplyToolHit"/>. Also publishes <see cref="ToolHitTarget"/>
    /// on the GameEventBus for feedback/audio.
    /// </summary>
    public void EmitToolHit(ToolHitContext hit)
    {
        // Publish tool hit event for feedback/audio
        PublishEvent(new ToolHitTarget(hit));

        // Find and apply to resource nodes
        if (hit.Source == null) return;
        ResourceNode node = hit.Source.GetComponentInParent<ResourceNode>();
        if (node == null && ResourceManager.Instance != null)
        {
            // Legacy: try to find a ResourceNode on the hit target
            // (the hit.Source is the player, not the target — need different resolution)
        }

        // Also raise through the legacy ResourceManager path for backward compat
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.RaiseHit(new PlayerHitInfo(hit.HitPoint, hit.Source, hit.Damage));
    }

    /// <summary>Player-side reaction to resource events. Empty hook for now.</summary>
    private void HandleResourceHit(PlayerHitInfo info) { }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;

/// <summary>
/// Push/pull objects with E. When the player grabs a <see cref="Grabbable"/>, they
/// lock onto whichever face they approached from. The object stays on the ground on
/// that side of the player while they walk — walking toward the crate pushes it,
/// walking away pulls it, walking sideways translates both. The crate never rotates
/// around the player. Press E again to release.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerCarryController : MonoBehaviour
{
    [SerializeField] private KeyCode _grabKey = KeyCode.E;

    [Header("Push/pull positioning")]
    [Tooltip("Extra gap between the player and the held object to prevent overlap with the player's capsule.")]
    [SerializeField] private float _skinWidth = 0.15f;
    [Tooltip("How fast the held object tracks its target position.")]
    [SerializeField] private float _trackingSpeed = 20f;

    [Header("Movement")]
    [Tooltip("Speed multiplier applied to the player while carrying an object (0–1, lower = slower).")]
    [SerializeField, Range(0.1f, 1f)] private float _carrySpeedMultiplier = 0.6f;

    private PlayerMouseAimer _aimer;
    private Grabbable _heldObject;
    private Rigidbody _playerRb;
    private SolarpunkCharacterController _controller;

    // The locked hold side: unit vector from crate center toward the player at grab time,
    // snapped to the nearest cardinal axis (±X or ±Z).
    private Vector3 _holdSide;

    // Distance from the player center to the crate center along the hold-side axis.
    private float _holdDistance;

    // The crate's ground Y so it stays on the floor.
    private float _crateGroundY;

    /// <summary>True while carrying an object.</summary>
    public bool IsCarrying => _heldObject != null;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _playerRb = GetComponent<Rigidbody>();
        _controller = GetComponent<SolarpunkCharacterController>();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(_grabKey)) return;

        if (IsCarrying)
        {
            Release();
            return;
        }

        Grabbable target = FindGrabbableTarget();
        if (target != null && !target.IsHeld)
            Grab(target);
    }

    private void LateUpdate()
    {
        if (!IsCarrying || _heldObject == null) return;

        // Position the crate on the locked hold side of the player.
        Vector3 playerPos = transform.position;
        Vector3 crateTarget = playerPos - _holdSide * _holdDistance;
        crateTarget.y = _crateGroundY;

        _heldObject.transform.position = Vector3.Lerp(
            _heldObject.transform.position, crateTarget, _trackingSpeed * Time.deltaTime);

        // Keep the crate upright and unmoving rotationally
        _heldObject.transform.rotation = Quaternion.identity;
    }

    private void FixedUpdate()
    {
        // Slow the player while carrying
        if (_controller != null && IsCarrying)
            _controller.SpeedMultiplier = _carrySpeedMultiplier;
    }

    /// <summary>Find a Grabbable under the cursor within interaction range.</summary>
    private Grabbable FindGrabbableTarget()
    {
        if (_aimer == null) return null;

        IInteractionPromptProvider interactable = _aimer.HoveredInteractable;
        if (interactable is Grabbable grabbable)
            return grabbable;

        GameObject hovered = _aimer.HoveredGameObject;
        if (hovered != null)
        {
            Grabbable g = hovered.GetComponentInParent<Grabbable>();
            if (g != null)
            {
                float dist = Vector3.Distance(transform.position, g.transform.position);
                if (dist <= _aimer.InteractionRange)
                    return g;
            }
        }

        return null;
    }

    private void Grab(Grabbable target)
    {
        _heldObject = target;

        // Determine which face the player is on
        Vector3 toPlayer = transform.position - target.transform.position;
        toPlayer.y = 0f;
        _holdSide = SnapToCardinal(toPlayer);

        // Calculate the hold distance: player half-extent + crate half-extent + skin.
        // The skin width keeps the player's capsule clearly outside the crate so
        // the physics solver never sees an overlap.
        float playerRadius = 0.23f;
        float crateExtent = GetExtentsAlong(target, _holdSide);
        _holdDistance = playerRadius + crateExtent + _skinWidth;

        // Remember the crate's Y so it stays grounded
        _crateGroundY = target.transform.position.y;

        _heldObject.OnGrab();
    }

    private void Release()
    {
        if (_heldObject == null) return;

        _heldObject.OnRelease();
        _heldObject = null;

        if (_controller != null) _controller.SpeedMultiplier = 1f;
    }

    /// <summary>
    /// Force-release the carried object (e.g. if it's destroyed or the player enters
    /// a state where carrying isn't allowed). Called externally.
    /// </summary>
    public void ForceRelease()
    {
        if (_heldObject != null) _heldObject.OnRelease();
        _heldObject = null;
        if (_controller != null) _controller.SpeedMultiplier = 1f;
    }

    private static Vector3 SnapToCardinal(Vector3 dir)
    {
        if (dir.sqrMagnitude < 0.001f) return Vector3.right;

        float absX = Mathf.Abs(dir.x);
        float absZ = Mathf.Abs(dir.z);

        if (absX >= absZ)
            return new Vector3(Mathf.Sign(dir.x), 0f, 0f);
        else
            return new Vector3(0f, 0f, Mathf.Sign(dir.z));
    }

    private static float GetExtentsAlong(Grabbable target, Vector3 axis)
    {
        Collider col = target.GetComponent<Collider>();
        if (col != null)
        {
            if (Mathf.Abs(axis.x) > 0.5f) return col.bounds.extents.x;
            if (Mathf.Abs(axis.z) > 0.5f) return col.bounds.extents.z;
        }
        return 0.5f;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Drops items from the inventory back into the world. <b>G</b> drops one unit of the active slot;
/// the HUD calls <see cref="DropSlot"/> to drop a whole stack via drag-off-the-bar. Dropped items
/// spawn through <see cref="WorldItemSpawner"/> and get a short re-collect delay so an auto-collecting
/// resource doesn't instantly fly back into the inventory.
/// </summary>
public class PlayerDropController : MonoBehaviour
{
    [SerializeField] private KeyCode _dropKey = KeyCode.G;
    [SerializeField] private float _dropForward = 0.8f;
    [SerializeField] private float _dropHeight = 0.6f;
    [SerializeField] private float _popImpulse = 2f;
    [Tooltip("Seconds before a dropped auto-collect item may fly back to the player.")]
    [SerializeField] private float _reCollectDelay = 1.5f;

    private static PlayerInventory Inv => PlayerInventory.Instance;

    private void Update()
    {
        if (Input.GetKeyDown(_dropKey) && Inv != null)
            DropFromSlot(Inv.ActiveSlotIndex, wholeStack: false);
    }

    /// <summary>Drop the entire stack in a slot (used by the hotbar drag-to-drop).</summary>
    public void DropSlot(int index) => DropFromSlot(index, wholeStack: true);

    private void DropFromSlot(int index, bool wholeStack)
    {
        if (Inv == null) return;
        InventorySlot slot = Inv.GetSlot(index);
        if (slot.IsEmpty) return;

        ItemDefinition item = slot.item;
        // No world prefab → can't represent it on the ground; abort rather than vanish the item.
        if (item == null || item.worldPrefab == null)
        {
            Debug.LogWarning($"[PlayerDropController] '{(item != null ? item.displayName : "null")}' has no worldPrefab; drop ignored.", this);
            return;
        }

        int count;
        if (wholeStack) Inv.RemoveStack(index, out count);
        else          { Inv.RemoveOne(index); count = 1; }

        if (item == null || count <= 0) return;

        Vector3 pos = transform.position + Vector3.up * _dropHeight + transform.forward * _dropForward;
        WorldItem dropped = WorldItemSpawner.Spawn(item, count, pos, _popImpulse);
        if (dropped != null)
        {
            DroppedItemMagnet magnet = dropped.GetComponent<DroppedItemMagnet>();
            if (magnet != null) magnet.Suppress(_reCollectDelay);
        }

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ItemDropped(item, count, pos));
    }
}

