using Flynn.Events;

/// <summary>
/// Player startup script. Owns the player's wiring to the <see cref="ResourceManager"/>:
/// it subscribes to resource events on startup and is the publisher that raises player hits
/// via <see cref="EmitHit"/>. Also supports the new <see cref="ToolHitContext"/>-based
/// hit flow that routes through <see cref="ResourceNode.TryApplyToolHit"/> with tool
/// effectiveness lookups.
/// </summary>
public class PlayerInitializer : MonoBehaviour
{
    [Header("Debug")]
    [Tooltip("Press to raise a test hit at the player's position (verifies the event pipe). None = disabled.")]
    [SerializeField] private KeyCode _debugHitKey = KeyCode.None;

    private void OnEnable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit += HandleResourceHit;
    }

    private void OnDisable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit -= HandleResourceHit;
    }

    private void Update()
    {
        if (_debugHitKey != KeyCode.None && Input.GetKeyDown(_debugHitKey))
            EmitHit(transform.position, null, 1);
    }

    /// <summary>Publisher: raise a player hit through the manager (legacy PlayerHitInfo path).</summary>
    public void EmitHit(Vector3 point, GameObject target = null, int power = 1)
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.RaiseHit(new PlayerHitInfo(point, target, power));
    }

    /// <summary>
    /// Publisher: raise a tool hit with full context. Routes through the effectiveness
    /// system by finding the <see cref="ResourceNode"/> on the target and calling
    /// <see cref="ResourceNode.TryApplyToolHit"/>. Also publishes <see cref="ToolHitTarget"/>
    /// on the GameEventBus for feedback/audio.
    /// </summary>
    public void EmitToolHit(ToolHitContext hit)
    {
        // Publish tool hit event for feedback/audio
        PublishEvent(new ToolHitTarget(hit));

        // Find and apply to resource nodes
        if (hit.Source == null) return;
        ResourceNode node = hit.Source.GetComponentInParent<ResourceNode>();
        if (node == null && ResourceManager.Instance != null)
        {
            // Legacy: try to find a ResourceNode on the hit target
            // (the hit.Source is the player, not the target — need different resolution)
        }

        // Also raise through the legacy ResourceManager path for backward compat
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.RaiseHit(new PlayerHitInfo(hit.HitPoint, hit.Source, hit.Damage));
    }

    /// <summary>Player-side reaction to resource events. Empty hook for now.</summary>
    private void HandleResourceHit(PlayerHitInfo info) { }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;

/// <summary>
/// Push/pull objects with E. When the player grabs a <see cref="Grabbable"/>, they
/// lock onto whichever face they approached from. The object stays on the ground on
/// that side of the player while they walk — walking toward the crate pushes it,
/// walking away pulls it, walking sideways translates both. The crate never rotates
/// around the player. Press E again to release.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerCarryController : MonoBehaviour
{
    [SerializeField] private KeyCode _grabKey = KeyCode.E;

    [Header("Push/pull positioning")]
    [Tooltip("Extra gap between the player and the held object to prevent overlap with the player's capsule.")]
    [SerializeField] private float _skinWidth = 0.15f;
    [Tooltip("How fast the held object tracks its target position.")]
    [SerializeField] private float _trackingSpeed = 20f;

    [Header("Movement")]
    [Tooltip("Speed multiplier applied to the player while carrying an object (0–1, lower = slower).")]
    [SerializeField, Range(0.1f, 1f)] private float _carrySpeedMultiplier = 0.6f;

    private PlayerMouseAimer _aimer;
    private Grabbable _heldObject;
    private Rigidbody _playerRb;
    private SolarpunkCharacterController _controller;

    // The locked hold side: unit vector from crate center toward the player at grab time,
    // snapped to the nearest cardinal axis (±X or ±Z).
    private Vector3 _holdSide;

    // Distance from the player center to the crate center along the hold-side axis.
    private float _holdDistance;

    // The crate's ground Y so it stays on the floor.
    private float _crateGroundY;

    /// <summary>True while carrying an object.</summary>
    public bool IsCarrying => _heldObject != null;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _playerRb = GetComponent<Rigidbody>();
        _controller = GetComponent<SolarpunkCharacterController>();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(_grabKey)) return;

        if (IsCarrying)
        {
            Release();
            return;
        }

        Grabbable target = FindGrabbableTarget();
        if (target != null && !target.IsHeld)
            Grab(target);
    }

    private void LateUpdate()
    {
        if (!IsCarrying || _heldObject == null) return;

        // Position the crate on the locked hold side of the player.
        Vector3 playerPos = transform.position;
        Vector3 crateTarget = playerPos - _holdSide * _holdDistance;
        crateTarget.y = _crateGroundY;

        _heldObject.transform.position = Vector3.Lerp(
            _heldObject.transform.position, crateTarget, _trackingSpeed * Time.deltaTime);

        // Keep the crate upright and unmoving rotationally
        _heldObject.transform.rotation = Quaternion.identity;
    }

    private void FixedUpdate()
    {
        // Slow the player while carrying
        if (_controller != null && IsCarrying)
            _controller.SpeedMultiplier = _carrySpeedMultiplier;
    }

    /// <summary>Find a Grabbable under the cursor within interaction range.</summary>
    private Grabbable FindGrabbableTarget()
    {
        if (_aimer == null) return null;

        IInteractionPromptProvider interactable = _aimer.HoveredInteractable;
        if (interactable is Grabbable grabbable)
            return grabbable;

        GameObject hovered = _aimer.HoveredGameObject;
        if (hovered != null)
        {
            Grabbable g = hovered.GetComponentInParent<Grabbable>();
            if (g != null)
            {
                float dist = Vector3.Distance(transform.position, g.transform.position);
                if (dist <= _aimer.InteractionRange)
                    return g;
            }
        }

        return null;
    }

    private void Grab(Grabbable target)
    {
        _heldObject = target;

        // Determine which face the player is on
        Vector3 toPlayer = transform.position - target.transform.position;
        toPlayer.y = 0f;
        _holdSide = SnapToCardinal(toPlayer);

        // Calculate the hold distance: player half-extent + crate half-extent + skin.
        // The skin width keeps the player's capsule clearly outside the crate so
        // the physics solver never sees an overlap.
        float playerRadius = 0.23f;
        float crateExtent = GetExtentsAlong(target, _holdSide);
        _holdDistance = playerRadius + crateExtent + _skinWidth;

        // Remember the crate's Y so it stays grounded
        _crateGroundY = target.transform.position.y;

        _heldObject.OnGrab();
    }

    private void Release()
    {
        if (_heldObject == null) return;

        _heldObject.OnRelease();
        _heldObject = null;

        if (_controller != null) _controller.SpeedMultiplier = 1f;
    }

    /// <summary>
    /// Force-release the carried object (e.g. if it's destroyed or the player enters
    /// a state where carrying isn't allowed). Called externally.
    /// </summary>
    public void ForceRelease()
    {
        if (_heldObject != null) _heldObject.OnRelease();
        _heldObject = null;
        if (_controller != null) _controller.SpeedMultiplier = 1f;
    }

    private static Vector3 SnapToCardinal(Vector3 dir)
    {
        if (dir.sqrMagnitude < 0.001f) return Vector3.right;

        float absX = Mathf.Abs(dir.x);
        float absZ = Mathf.Abs(dir.z);

        if (absX >= absZ)
            return new Vector3(Mathf.Sign(dir.x), 0f, 0f);
        else
            return new Vector3(0f, 0f, Mathf.Sign(dir.z));
    }

    private static float GetExtentsAlong(Grabbable target, Vector3 axis)
    {
        Collider col = target.GetComponent<Collider>();
        if (col != null)
        {
            if (Mathf.Abs(axis.x) > 0.5f) return col.bounds.extents.x;
            if (Mathf.Abs(axis.z) > 0.5f) return col.bounds.extents.z;
        }
        return 0.5f;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Drops items from the inventory back into the world. <b>G</b> drops one unit of the active slot;
/// the HUD calls <see cref="DropSlot"/> to drop a whole stack via drag-off-the-bar. Dropped items
/// spawn through <see cref="WorldItemSpawner"/> and get a short re-collect delay so an auto-collecting
/// resource doesn't instantly fly back into the inventory.
/// </summary>
public class PlayerDropController : MonoBehaviour
{
    [SerializeField] private KeyCode _dropKey = KeyCode.G;
    [SerializeField] private float _dropForward = 0.8f;
    [SerializeField] private float _dropHeight = 0.6f;
    [SerializeField] private float _popImpulse = 2f;
    [Tooltip("Seconds before a dropped auto-collect item may fly back to the player.")]
    [SerializeField] private float _reCollectDelay = 1.5f;

    private static PlayerInventory Inv => PlayerInventory.Instance;

    private void Update()
    {
        if (Input.GetKeyDown(_dropKey) && Inv != null)
            DropFromSlot(Inv.ActiveSlotIndex, wholeStack: false);
    }

    /// <summary>Drop the entire stack in a slot (used by the hotbar drag-to-drop).</summary>
    public void DropSlot(int index) => DropFromSlot(index, wholeStack: true);

    private void DropFromSlot(int index, bool wholeStack)
    {
        if (Inv == null) return;
        InventorySlot slot = Inv.GetSlot(index);
        if (slot.IsEmpty) return;

        ItemDefinition item = slot.item;
        // No world prefab → can't represent it on the ground; abort rather than vanish the item.
        if (item == null || item.worldPrefab == null)
        {
            Debug.LogWarning($"[PlayerDropController] '{(item != null ? item.displayName : "null")}' has no worldPrefab; drop ignored.", this);
            return;
        }

        int count;
        if (wholeStack) Inv.RemoveStack(index, out count);
        else          { Inv.RemoveOne(index); count = 1; }

        if (item == null || count <= 0) return;

        Vector3 pos = transform.position + Vector3.up * _dropHeight + transform.forward * _dropForward;
        WorldItem dropped = WorldItemSpawner.Spawn(item, count, pos, _popImpulse);
        if (dropped != null)
        {
            DroppedItemMagnet magnet = dropped.GetComponent<DroppedItemMagnet>();
            if (magnet != null) magnet.Suppress(_reCollectDelay);
        }

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ItemDropped(item, count, pos));
    }
}

