using System;
using UnityEngine;

/// <summary>
/// Owns the runtime inventory state (copied from <see cref="InventoryData"/> on Awake — the SO
/// itself is never mutated at runtime). Holds a flat array of <see cref="InventorySlot"/>s:
/// slot 0 is the wrench slot, slots 1..N are general item slots that stack identical items up to
/// <see cref="ItemDefinition.maxStack"/>. The slot count is data-driven and extendable.
///
/// Accepts any item kind (resources, future tools, etc.). Currency items never enter a slot —
/// they route to their <see cref="ItemDefinition.currencyTarget"/> at the collection site.
/// Handles hotkey input (1-4) to switch the active slot; raises events for the HUD.
///
/// Acts as the game's inventory manager: a singleton (<see cref="Instance"/>) so the HUD, pickup,
/// drop, magnets and the wrench controllers all reach inventory through one access point and
/// subscribe to its events — no FindObjectOfType, no per-system GetComponent. Single-player, so one
/// instance is assumed. Runs early (negative execution order) so <see cref="Instance"/> exists
/// before any subscriber's Awake/OnEnable.
///
/// Pure manager — holds no scene-position state and never touches the character controller, so it
/// lives on a dedicated manager GameObject (e.g. MANAGERS/INVENTORY), not on the Player. All users
/// reach it through <see cref="Instance"/>; nothing requires it to share the Player's GameObject.
/// </summary>
[DefaultExecutionOrder(-50)]
public class PlayerInventory : MonoBehaviour
{
    /// <summary>The active inventory manager. Set in Awake, cleared on destroy.</summary>
    public static PlayerInventory Instance { get; private set; }

    public const int WrenchSlot = 0;

    [SerializeField] private InventoryData _inventoryConfig;

    public event Action<int> OnSlotChanged;
    public event Action<int> OnActiveSlotChanged;

    private InventorySlot[] _runtimeSlots = Array.Empty<InventorySlot>();
    private int _activeSlot;

    // ── Public API ────────────────────────────────────────────────────────────

    public int SlotCount => _runtimeSlots.Length;

    public int ActiveSlotIndex
    {
        get => _activeSlot;
        private set
        {
            int clamped = Mathf.Clamp(value, 0, SlotCount - 1);
            if (_activeSlot == clamped) return;
            _activeSlot = clamped;
            OnActiveSlotChanged?.Invoke(_activeSlot);
        }
    }

    public InventorySlot ActiveSlot => GetSlot(_activeSlot);
    public ItemDefinition ActiveItem => ActiveSlot.item;

    /// <summary>ItemType of the currently selected slot, or None if it's empty.</summary>
    public ItemType ActiveItemType => ActiveItem != null ? ActiveItem.itemType : ItemType.None;

    /// <summary>True when no general slot is empty (can't accept a new item kind).</summary>
    public bool IsFull
    {
        get
        {
            for (int i = 1; i < _runtimeSlots.Length; i++)
                if (_runtimeSlots[i].IsEmpty) return false;
            return true;
        }
    }

    public InventorySlot GetSlot(int index)
    {
        if (index < 0 || index >= _runtimeSlots.Length) return InventorySlot.Empty;
        return _runtimeSlots[index];
    }

    /// <summary>True if any slot currently holds an item of the given type.</summary>
    public bool HasItem(ItemType type)
    {
        for (int i = 0; i < _runtimeSlots.Length; i++)
            if (!_runtimeSlots[i].IsEmpty && _runtimeSlots[i].item.itemType == type) return true;
        return false;
    }

    /// <summary>
    /// True if at least one unit of <paramref name="item"/> can be accepted right now
    /// (a matching non-full stack, or an empty slot). Used by world-item magnets to decide
    /// whether to fly to the player or stay on the ground.
    /// </summary>
    public bool HasRoomFor(ItemDefinition item)
    {
        if (item == null || item.isCurrency) return false;

        if (item.itemType == ItemType.Wrench)
            return GetSlot(WrenchSlot).IsEmpty;

        for (int i = 1; i < _runtimeSlots.Length; i++)
        {
            if (_runtimeSlots[i].IsEmpty) return true;
            if (_runtimeSlots[i].item == item && !_runtimeSlots[i].IsFull) return true;
        }
        return false;
    }

    /// <summary>
    /// Add up to <paramref name="count"/> of <paramref name="item"/>, stacking into matching
    /// slots first then filling empty ones. Returns how many were actually added (0 = no room).
    /// Currency items are rejected here (they belong on the currency counter, not a slot).
    /// </summary>
    public int TryAddItem(ItemDefinition item, int count = 1)
    {
        if (item == null || count <= 0 || item.isCurrency) return 0;

        if (item.itemType == ItemType.Wrench)
        {
            if (!GetSlot(WrenchSlot).IsEmpty) return 0;
            _runtimeSlots[WrenchSlot] = InventorySlot.Of(item, 1);
            OnSlotChanged?.Invoke(WrenchSlot);
            return 1;
        }

        int added = 0;

        // 1) Top up existing matching stacks.
        for (int i = 1; i < _runtimeSlots.Length && added < count; i++)
        {
            if (_runtimeSlots[i].item != item || _runtimeSlots[i].IsFull) continue;
            int take = Mathf.Min(_runtimeSlots[i].SpaceLeft, count - added);
            _runtimeSlots[i].count += take;
            added += take;
            OnSlotChanged?.Invoke(i);
        }

        // 2) Fill empty slots.
        for (int i = 1; i < _runtimeSlots.Length && added < count; i++)
        {
            if (!_runtimeSlots[i].IsEmpty) continue;
            int take = Mathf.Min(Mathf.Max(1, item.maxStack), count - added);
            _runtimeSlots[i] = InventorySlot.Of(item, take);
            added += take;
            OnSlotChanged?.Invoke(i);
        }

        return added;
    }

    /// <summary>Remove one unit from a slot; returns the item removed, or null if the slot was empty.</summary>
    public ItemDefinition RemoveOne(int index) => RemoveFromSlot(index, 1, out _);

    /// <summary>Remove the whole stack from a slot; returns the item and (via out) how many were removed.</summary>
    public ItemDefinition RemoveStack(int index, out int removed)
        => RemoveFromSlot(index, int.MaxValue, out removed);

    /// <summary>Remove up to <paramref name="count"/> units from a slot.</summary>
    public ItemDefinition RemoveFromSlot(int index, int count, out int removed)
    {
        removed = 0;
        if (index < 0 || index >= _runtimeSlots.Length || count <= 0) return null;

        InventorySlot slot = _runtimeSlots[index];
        if (slot.IsEmpty) return null;

        ItemDefinition item = slot.item;
        removed = Mathf.Min(count, slot.count);
        slot.count -= removed;
        _runtimeSlots[index] = slot.count <= 0 ? InventorySlot.Empty : slot;
        OnSlotChanged?.Invoke(index);
        return item;
    }

    // ── Signals (inbound) ───────────────────────────────────────────────────────
    // Readability aliases over the API above. Same pattern as ResourceManager.RaiseHit:
    // a gameplay system "signals" the inventory (e.g. a pickup collision), the inventory
    // mutates its slots, then broadcasts OnSlotChanged / OnActiveSlotChanged outward.
    // The store is the one place that owns slot state — these just read like events.

    /// <summary>Signal: an item pickup was requested (e.g. by a collision/magnet). Returns how
    /// many units actually entered the inventory. Forwards to <see cref="TryAddItem"/>.</summary>
    public int SignalPickup(ItemDefinition item, int count = 1) => TryAddItem(item, count);

    /// <summary>Signal: drop one unit from a slot. Returns the item removed, or null if empty.
    /// Forwards to <see cref="RemoveOne"/>.</summary>
    public ItemDefinition SignalDropOne(int slot) => RemoveOne(slot);

    /// <summary>Signal: drop a whole stack from a slot. Forwards to <see cref="RemoveStack"/>.</summary>
    public ItemDefinition SignalDropStack(int slot, out int removed) => RemoveStack(slot, out removed);

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
            Debug.LogWarning($"[PlayerInventory] Second instance on '{name}'; overriding the previous Instance.", this);
        Instance = this;

        int count = _inventoryConfig != null ? _inventoryConfig.Slots : 4;
        _runtimeSlots = new InventorySlot[count];
        for (int i = 0; i < count; i++)
        {
            ItemDefinition def = _inventoryConfig != null ? _inventoryConfig.GetDefaultSlot(i) : null;
            _runtimeSlots[i] = def != null ? InventorySlot.Of(def, 1) : InventorySlot.Empty;
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        ReadHotkeys();
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void ReadHotkeys()
    {
        if (Input.GetKeyDown(KeyCode.Alpha1))      ActiveSlotIndex = 0;
        else if (Input.GetKeyDown(KeyCode.Alpha2)) ActiveSlotIndex = 1;
        else if (Input.GetKeyDown(KeyCode.Alpha3)) ActiveSlotIndex = 2;
        else if (Input.GetKeyDown(KeyCode.Alpha4)) ActiveSlotIndex = 3;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Picks up the key-pickup <see cref="WorldItem"/> the player is aiming at when the pickup key is
/// pressed: grants its item(s) to the inventory and removes it from the world. Only non-auto-collect
/// items (e.g. the wrench) need this — auto-collect drops fly to the player on their own.
/// Reads the hovered item from <see cref="PlayerMouseAimer"/>; writes to <see cref="PlayerInventory"/>.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerPickupController : MonoBehaviour
{
    [SerializeField] private KeyCode _pickupKey = KeyCode.E;

    private PlayerMouseAimer _aimer;
    private PlayerCarryController _carry;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _carry = GetComponent<PlayerCarryController>();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(_pickupKey)) return;

        // Skip pickup while carrying an object
        if (_carry != null && _carry.IsCarrying) return;

        WorldItem item = _aimer.HoveredKeyPickup;
        if (item == null || item.Item == null) return;

        PlayerInventory inv = PlayerInventory.Instance;
        if (inv == null) return;

        int added = inv.TryAddItem(item.Item, item.Count);
        if (added <= 0) return;

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ItemPickedUp(item.Item, added));

        if (added >= item.Count) Destroy(item.gameObject);
        else                     item.Reduce(added);
    }
}

using UnityEngine;

/// <summary>
/// Handles the scan interaction flow: holds F to scan a ScanTarget under the cursor.
/// Reads the current ScanTarget from <see cref="PlayerMouseAimer.HoverResult"/> each frame.
/// On key down: validates and calls <see cref="ScanTarget.Begin"/>.
/// While held: calls <see cref="ScanTarget.TickScan"/> and drains battery.
/// On key up or target lost: calls <see cref="ScanTarget.CancelScan"/>.
///
/// The <see cref="WorldInteractTagPresenter"/> already shows the scan progress text
/// by subscribing to <see cref="Flynn.Events.ScanProgressed"/> events.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerScanController : MonoBehaviour
{
    [Tooltip("Key to hold for scanning.")]
    [SerializeField] private KeyCode _scanKey = KeyCode.F;

    private PlayerMouseAimer _aimer;
    private RobotBattery _battery;
    private ScanTarget _activeTarget;
    private bool _keyHeld;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _battery = RobotBattery.Instance;
    }

    private void Update()
    {
        bool keyDown = Input.GetKeyDown(_scanKey);
        bool keyUp = Input.GetKeyUp(_scanKey);
        _keyHeld = Input.GetKey(_scanKey);

        var scanTarget = _aimer != null ? _aimer.HoverResult.ScanTarget : null;

        // Start scan on key down
        if (keyDown && scanTarget != null && scanTarget.CanStart())
        {
            _activeTarget = scanTarget;
            _activeTarget.Begin();
        }

        // Tick while held and target is valid
        if (_keyHeld && _activeTarget != null && _activeTarget.IsScanning)
        {
            // Verify target is still the one under cursor
            if (scanTarget != _activeTarget)
            {
                CancelActive();
                return;
            }

            // Check battery
            float costPerSecond = _activeTarget.Config != null
                ? _activeTarget.Config.batteryCostPerSecond : 0f;

            if (costPerSecond > 0f && _battery != null && !_battery.CanSpend(costPerSecond * Time.deltaTime))
            {
                CancelActive();
                return;
            }

            _activeTarget.TickScan(Time.deltaTime);

            if (_battery != null && costPerSecond > 0f)
                _battery.DrainOverTime(costPerSecond);
        }

        // Cancel on key up or target lost
        if (keyUp || (_activeTarget != null && !_activeTarget.IsScanning))
        {
            CancelActive();
        }
    }

    private void CancelActive()
    {
        if (_activeTarget != null && _activeTarget.IsScanning)
            _activeTarget.CancelScan();
        _activeTarget = null;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Wrench grapple with swing physics. Hold Q to charge, release to fire.
/// A hook projectile travels from the player's visual center to the target,
/// then the player swings on the rope with pendulum physics (momentum preservation
/// on release). Grapples what the cursor is over (resolved by PlayerMouseAimer):
///   - RopeAnchor → swing the player around the anchor point
///   - RopePullable → reel the object toward the player
/// Blocked while on mud. Requires the wrench as the active item.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class RopeLassoController : MonoBehaviour
{
    [SerializeField] private RopeLassoConfig _config;
    [Tooltip("Rope visual. A child LineRenderer; enabled only while grappling.")]
    [SerializeField] private LineRenderer _ropeLine;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _controller;
    private TerrainStateAggregator _terrainState;
    private Rigidbody _rb;
    private PlayerCarryController _carry;

    // ── Charge ──────────────────────────────────────────────────────────────

    private float _chargeTimer;
    private bool _charging;

    // ── State machine ───────────────────────────────────────────────────────

    private enum GrappleState { Idle, Firing, Swinging, PullingObject }
    private GrappleState _state = GrappleState.Idle;

    // Firing state
    private Vector3 _fireStart;
    private Vector3 _fireTarget;
    private float _fireElapsed;

    // Swing state
    private Vector3 _anchorPoint;
    private float _ropeLength;
    private float _swingElapsed;

    // Pull state
    private Rigidbody _pullBody;
    private float _pullElapsed;

    // Rope visual
    private const int RopeSegments = 10;
    private Vector3[] _ropePoints;

    // Cached for end-event publishing
    private RopeAnchor _activeAnchor;
    private RopePullable _activePullable;

    // Actual world-space anchor (for visual), separate from the Y-projected _anchorPoint
    private Vector3 _anchorWorldPos;

    // ── Public API ──────────────────────────────────────────────────────────

    public bool IsCharging => _charging;
    public float ChargeNormalized => _config != null && _config.chargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.chargeTime) : 0f;
    public bool IsPulling => _state == GrappleState.Swinging || _state == GrappleState.PullingObject;
    public bool IsSwinging => _state == GrappleState.Swinging;

    /// <summary>
    /// Billboard visual centre — the rope leaves from the sprite's centre, not the feet.
    /// Uses the IPlayerVisual.VisualCenter which accounts for camera-tilt offset on
    /// the billboarded sprite.
    /// </summary>
    public Vector3 HandPoint => _animDriver != null ? _animDriver.VisualCenter : transform.position;

    // ── Awake ───────────────────────────────────────────────────────────────

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _controller = GetComponent<SolarpunkCharacterController>();
        _terrainState = GetComponent<TerrainStateAggregator>();
        _rb         = GetComponent<Rigidbody>();
        _carry      = GetComponent<PlayerCarryController>();

        _ropePoints = new Vector3[RopeSegments];

        if (_ropeLine != null)
        {
            _ropeLine.positionCount = RopeSegments;
            _ropeLine.enabled = false;
        }
    }

    // ── Update: input, charging, firing progress ────────────────────────────

    private void Update()
    {
        switch (_state)
        {
            case GrappleState.Idle:
                UpdateIdle();
                break;
            case GrappleState.Firing:
                UpdateFiring();
                break;
            case GrappleState.Swinging:
                UpdateSwingInput();
                break;
            case GrappleState.PullingObject:
                UpdatePullInput();
                break;
        }
    }

    private void UpdateIdle()
    {
        bool onMud = _terrainState != null
            ? _terrainState.CurrentTerrainState.BlocksRope
            : (_controller != null && !_controller.CanJump);
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !onMud
                      && (_carry == null || !_carry.IsCarrying);
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetKeyDown(KeyCode.Q))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetKey(KeyCode.Q))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetKeyUp(KeyCode.Q))
        {
            FireLasso();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void UpdateFiring()
    {
        _fireElapsed += Time.deltaTime;
        float fireDuration = _config != null ? _config.hookTravelTime : 0.12f;
        float t = Mathf.Clamp01(_fireElapsed / fireDuration);

        // Ease-out for a snappy travel feel
        float easedT = 1f - Mathf.Pow(1f - t, 3f);
        Vector3 hookPos = Vector3.Lerp(_fireStart, _fireTarget, easedT);

        // Draw extending rope from hand to hook tip (sag fades as hook approaches target)
        DrawRope(HandPoint, hookPos, slack: 0.4f * (1f - t));

        if (t >= 1f)
        {
            if (_activePullable != null)
                StartPullingObject();
            else
                StartSwinging();
        }
    }

    private void UpdateSwingInput()
    {
        // Release with Jump or Q
        if (Input.GetButtonDown("Jump") || Input.GetKeyDown(KeyCode.Q))
        {
            EndGrapple(preserveMomentum: true);
            return;
        }

        // Adjust rope length with scroll wheel
        if (_config != null)
        {
            float scroll = Input.mouseScrollDelta.y;
            if (scroll != 0f)
            {
                _ropeLength -= scroll * _config.ropeAdjustSpeed * Time.deltaTime;
                _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);
            }
        }
    }

    private void UpdatePullInput()
    {
        // Release pull with Q
        if (Input.GetKeyUp(KeyCode.Q))
            EndGrapple(preserveMomentum: false);
    }

    // ── Fire ────────────────────────────────────────────────────────────────

    private void FireLasso()
    {
        if (_config == null) return;

        RopeAnchor anchor = _aimer.HoveredAnchor;
        RopePullable pullable = _aimer.HoveredPullable;
        if (anchor == null && pullable == null) return;

        Vector3 grapplePoint = _aimer.HoveredGrapplePoint;
        float dist = Vector3.Distance(HandPoint, grapplePoint);
        if (dist < _config.minRange || dist > _config.maxRange) return;

        // Battery check
        var battery = RobotBattery.Instance;
        float grappleCost = battery != null && battery.Settings != null
            ? battery.Settings.grappleCost : 0f;
        if (battery != null && !battery.CanSpend(grappleCost)) return;
        if (battery != null && grappleCost > 0f) battery.Spend(grappleCost);

        // Cache targets for events
        _activeAnchor = anchor;
        _activePullable = pullable;

        // Start firing
        _state = GrappleState.Firing;
        _fireStart = HandPoint;
        _fireTarget = grapplePoint;
        _fireElapsed = 0f;

        // Face the target
        if (_animDriver != null) _animDriver.FaceWorldDirection(grapplePoint - transform.position);

        // Publish start event immediately
        if (GameEventBus.Instance != null)
        {
            if (pullable != null)
                GameEventBus.Instance.Publish(new RopePullStarted(pullable));
            else if (anchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleStarted(anchor));
        }
    }

    // ── State transitions ───────────────────────────────────────────────────

    private void StartSwinging()
    {
        _state = GrappleState.Swinging;
        _swingElapsed = 0f;

        // 2.5D: project the anchor onto the player's Y so the tether is horizontal-only.
        // The rope constrains on the XZ plane; Y is entirely gravity/jump controlled.
        _anchorPoint = new Vector3(_fireTarget.x, _rb.position.y, _fireTarget.z);
        _anchorWorldPos = _fireTarget;

        // Rope length = initial horizontal distance to anchor
        Vector3 toAnchorXZ = _anchorPoint - _rb.position;
        toAnchorXZ.y = 0f;
        _ropeLength = toAnchorXZ.magnitude;
        if (_config != null)
            _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);

        // Snap impulse toward anchor on XZ only (no vertical yank)
        if (_config != null && _config.snapForce > 0f && _rb != null)
        {
            Vector3 toAnchor = (_anchorPoint - _rb.position);
            toAnchor.y = 0f;
            if (toAnchor.sqrMagnitude > 0.01f)
                _rb.AddForce(toAnchor.normalized * _config.snapForce, ForceMode.Impulse);
        }

        // Suppress character controller so it doesn't fight the swing
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void StartPullingObject()
    {
        _state = GrappleState.PullingObject;
        _pullBody = _activePullable != null ? _activePullable.Body : null;
        _pullElapsed = 0f;

        if (_pullBody == null) { EndGrapple(false); return; }
    }

    // ── FixedUpdate: swing & pull physics ────────────────────────────────────

    private void FixedUpdate()
    {
        switch (_state)
        {
            case GrappleState.Swinging:
                UpdateSwingPhysics();
                break;
            case GrappleState.PullingObject:
                UpdatePullPhysics();
                break;
        }
    }

    private void UpdateSwingPhysics()
    {
        if (_rb == null) { EndGrapple(false); return; }

        _swingElapsed += Time.fixedDeltaTime;

        // Safety timeout
        if (_config != null && _swingElapsed >= _config.pullTimeout)
        {
            EndGrapple(true);
            return;
        }

        // Battery drain while swinging
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(true); return; }
        }

        // 2.5D: re-project anchor to player's Y each step so the tether stays horizontal
        // even as the player rises/falls from gravity and jumps.
        _anchorPoint = new Vector3(_anchorPoint.x, _rb.position.y, _anchorPoint.z);

        // Swing input: WASD adds tangential force on the XZ plane to pump the swing
        Vector3 inputDir = new Vector3(
            Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical")).normalized;
        if (inputDir.sqrMagnitude > 0.01f)
        {
            Vector3 toAnchorXZ = (_anchorPoint - _rb.position);
            toAnchorXZ.y = 0f;
            if (toAnchorXZ.sqrMagnitude > 0.001f)
            {
                toAnchorXZ.Normalize();
                // Tangent on XZ: perpendicular to the rope direction
                Vector3 tangent = inputDir - Vector3.Project(inputDir, toAnchorXZ);
                tangent.y = 0f;
                if (tangent.sqrMagnitude > 0.001f)
                {
                    tangent.Normalize();
                    float swingForce = _config != null ? _config.swingForce : 30f;
                    _rb.AddForce(tangent * swingForce, ForceMode.Acceleration);
                }
            }
        }

        // 2.5D: enforce rope length constraint on the XZ plane only.
        // Y is untouched — gravity and jumps work normally while tethered.
        Vector3 toAnchorVec = _anchorPoint - _rb.position;
        toAnchorVec.y = 0f;
        float currentDistXZ = toAnchorVec.magnitude;

        if (currentDistXZ > _ropeLength && currentDistXZ > 0.001f)
        {
            Vector3 dirXZ = toAnchorVec.normalized;

            // Correct XZ position to stay on the horizontal rope circle
            Vector3 corrected = _rb.position;
            corrected.x = _anchorPoint.x - dirXZ.x * _ropeLength;
            corrected.z = _anchorPoint.z - dirXZ.z * _ropeLength;
            _rb.position = corrected;

            // Remove outward radial XZ velocity (keep tangential + all Y velocity)
            Vector3 outwardXZ = new Vector3(-dirXZ.x, 0f, -dirXZ.z);
            float vOut = Vector3.Dot(new Vector3(_rb.velocity.x, 0f, _rb.velocity.z), outwardXZ);
            if (vOut > 0f)
            {
                Vector3 correction = outwardXZ * vOut;
                _rb.velocity -= correction;
            }

            // Cap XZ swing speed only (Y is free)
            Vector3 velXZ = new Vector3(_rb.velocity.x, 0f, _rb.velocity.z);
            if (_config != null && velXZ.magnitude > _config.maxSwingSpeed)
            {
                velXZ = velXZ.normalized * _config.maxSwingSpeed;
                _rb.velocity = new Vector3(velXZ.x, _rb.velocity.y, velXZ.z);
            }
        }

        // Suppress character controller each step (it auto-resets to 1)
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void UpdatePullPhysics()
    {
        if (_pullBody == null) { EndGrapple(false); return; }

        _pullElapsed += Time.fixedDeltaTime;
        if (_config != null && _pullElapsed >= _config.pullTimeout)
        {
            EndGrapple(false);
            return;
        }

        // Battery drain while pulling
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(false); return; }
        }

        // Pull the object toward the player's hand
        Vector3 target = HandPoint;
        Vector3 to = target - _pullBody.position;

        float stopRadius = _config != null ? _config.stopRadius : 0.8f;
        if (to.magnitude <= stopRadius)
        {
            EndGrapple(false);
            return;
        }

        float pullForce = _config != null ? _config.pullForce : 55f;
        float maxPullSpeed = _config != null ? _config.maxPullSpeed : 14f;

        _pullBody.AddForce(to.normalized * pullForce, ForceMode.Acceleration);
        if (_pullBody.velocity.magnitude > maxPullSpeed)
            _pullBody.velocity = _pullBody.velocity.normalized * maxPullSpeed;
    }

    // ── End grapple ─────────────────────────────────────────────────────────

    private void EndGrapple(bool preserveMomentum)
    {
        // Publish end events
        if (GameEventBus.Instance != null)
        {
            if (_activeAnchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleEnded(_activeAnchor));
            if (_activePullable != null)
                GameEventBus.Instance.Publish(new RopePullEnded(_activePullable));
        }

        // 2.5D: on swing release, just let momentum carry — no forced vertical boost.
        // The player keeps their current XZ swing velocity (tangential) plus whatever
        // Y velocity they have from gravity/jumps.

        // Restore character controller
        if (_controller != null) _controller.SteeringControl = 1f;

        _state = GrappleState.Idle;
        _pullBody = null;
        _swingElapsed = 0f;
        _pullElapsed = 0f;
        _activeAnchor = null;
        _activePullable = null;
    }

    // ── LateUpdate: rope visual ─────────────────────────────────────────────

    private void LateUpdate()
    {
        if (_ropeLine == null) return;

        switch (_state)
        {
            case GrappleState.Swinging:
                // Taut rope from hand to the actual world anchor (not Y-projected)
                DrawRope(HandPoint, _anchorWorldPos, slack: 0.02f);
                break;

            case GrappleState.PullingObject:
                if (_pullBody != null)
                    DrawRope(HandPoint, _pullBody.position, slack: 0.08f);
                else
                    _ropeLine.enabled = false;
                break;

            case GrappleState.Firing:
                // Handled in UpdateFiring
                break;

            default:
                _ropeLine.enabled = false;
                break;
        }
    }

    // ── Rope drawing with sag ───────────────────────────────────────────────

    /// <summary>
    /// Draw the rope from start to end with a parabolic sag.
    /// slack=0 → taut straight line; slack=0.3 → visible droop.
    /// </summary>
    private void DrawRope(Vector3 start, Vector3 end, float slack)
    {
        if (_ropeLine == null) return;

        _ropeLine.enabled = true;

        float dist = Vector3.Distance(start, end);

        for (int i = 0; i < RopeSegments; i++)
        {
            float t = (float)i / (RopeSegments - 1);
            Vector3 point = Vector3.Lerp(start, end, t);

            // Parabolic sag: max at middle, zero at ends
            float sagAmount = slack * 4f * t * (1f - t) * dist;
            point += Vector3.down * sagAmount;

            _ropePoints[i] = point;
        }

        _ropeLine.SetPositions(_ropePoints);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Left-click swing for the wrench multitool. Hold to charge power via
/// <see cref="PowerBuildupManager"/>; release to swing with scaled damage and
/// battery cost. Tap for a light swing. The swing faces the mouse aim point.
/// Routes damage through the ResourceManager observer pattern.
/// Disabled while the wrench is airborne (thrown).
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [SerializeField] private PowerBuildupSettings _buildupSettings;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    [Tooltip("Cooldown between swings (seconds).")]
    [SerializeField] private float _cooldownTime = 0.1f;

    [Tooltip("Max distance from player for a melee hit. Beyond this is just a whoosh.")]
    [SerializeField] private float _swingRange = 1.5f;

    [Tooltip("Hold longer than this (seconds) to enter windup. Taps skip straight to swing.")]
    [SerializeField] private float _quickSwingThreshold = 0.12f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _movement;
    private PowerBuildupManager _buildup;
    private float _cooldown;
    private float _windupStartTime;

    public bool IsCharging => _buildup != null && _buildup.IsCharging && _buildup.CurrentType == ActionType.Swing;
    public float ChargeNormalized => _buildup != null ? _buildup.ChargeNormalized : 0f;

    /// <summary>True while the swing animation is still playing (movement blocked).</summary>
    public bool IsSwinging { get; private set; }

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
        _movement   = GetComponent<SolarpunkCharacterController>();
    }

    private void Update()
    {
        // Block movement while swinging
        if (IsSwinging)
        {
            if (_movement != null) _movement.CanMove = false;

            // Check if the swing animation has finished
            var driver = _animDriver as FlynnAnimationDriver;
            if (driver != null && !driver.IsAttacking)
                IsSwinging = false;
        }

        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable)
        {
            if (IsCharging) _buildup.CancelCharge();
            if (_animDriver is FlynnAnimationDriver drv)
                drv.CancelSwingWindup();
            return;
        }

        if (_buildup == null) _buildup = PowerBuildupManager.Instance;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
        {
            if (_buildup != null) _buildup.BeginCharge(ActionType.Swing);
            _windupStartTime = Time.time;
            // Face the mouse aim point and start the windup animation
            if (_animDriver != null)
            {
                _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);
                _animDriver.BeginSwingWindup();
            }
        }
        else if (IsCharging && Input.GetMouseButtonUp(0))
        {
            bool quickSwing = Time.time - _windupStartTime < _quickSwingThreshold;
            DoSwing(quickSwing);
        }
    }

    private void DoSwing(bool quickSwing = false)
    {
        if (_buildup == null) return;

        ChargeResult result = _buildup.ReleaseCharge();

        // Face the swing toward the mouse direction regardless of range
        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = result.AnimSpeed > 0f ? result.AnimSpeed : 1f;
        if (_animDriver != null)
        {
            if (quickSwing)
            {
                _animDriver.CancelSwingWindup();
                _animDriver.TriggerSwing();
            }
            else
            {
                _animDriver.ReleaseSwing(animIndex, speed);
            }
        }

        IsSwinging = true;
        if (_movement != null) _movement.CanMove = false;

        // Only apply damage if a hittable target (ResourceNode or HittableSurface) is within swing range
        bool inRange = false;
        Vector3 hitPoint = transform.position;

        if (_aimer.MeleeResource != null)
        {
            // ResourceNode within the aimer's melee range — also check our tighter swing range
            float dist = Vector3.Distance(transform.position, _aimer.WorldAimPoint);
            if (dist <= _swingRange)
            {
                inRange = true;
                hitPoint = _aimer.WorldAimPoint;
            }
        }
        else if (_aimer.HoveredGameObject != null)
        {
            // Check for HittableSurface (non-resource props) within swing range
            var surface = _aimer.HoveredGameObject.GetComponentInParent<HittableSurface>();
            float dist = Vector3.Distance(transform.position, _aimer.WorldAimPoint);
            if (surface != null && dist <= _swingRange)
            {
                inRange = true;
                hitPoint = _aimer.WorldAimPoint;
            }
        }
        // Ground / distant objects = whoosh (no damage)

        if (_swingArc != null)
            _swingArc.Play(hitPoint);

        _cooldown = _cooldownTime;

        if (inRange)
        {
            int damage = result.Damage > 0 ? result.Damage : 1;
            GameObject target = _aimer.HoveredGameObject;
            if (_playerInit != null && damage > 0)
                _playerInit.EmitHit(hitPoint, target, damage);
        }

        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;
        PublishEvent(new ToolSwingStarted(tool, hitPoint));
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Right-click throw for the wrench. Hold to charge power via
/// <see cref="PowerBuildupManager"/>; release to throw with scaled distance,
/// damage, and battery cost. Tap for a short light throw. Spawns a ThrownWrench
/// projectile that flies to the target, hovers, then boomerangs back.
/// Only one throw may be airborne at a time.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchThrowController : MonoBehaviour
{
    [SerializeField] private WrenchConfig _config;
    [SerializeField] private GameObject _thrownWrenchPrefab;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private ThrownWrench _airborne;
    private PowerBuildupManager _buildup;

    public bool IsCharging => _buildup != null && _buildup.IsCharging && _buildup.CurrentType == ActionType.Throw;
    public bool IsAirborne => _airborne != null;
    public float ChargeNormalized => _buildup != null ? _buildup.ChargeNormalized : 0f;

    /// <summary>
    /// World-space hand position: the billboard visual centre, so the wrench
    /// appears to leave from and return to the sprite rather than the physics root.
    /// </summary>
    public Vector3 CatchPoint =>
        _animDriver != null ? _animDriver.VisualCenter : transform.position;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
    }

    private void Update()
    {
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !IsAirborne;
        if (!usable)
        {
            if (IsCharging) _buildup.CancelCharge();
            return;
        }

        if (_buildup == null) _buildup = PowerBuildupManager.Instance;

        if (Input.GetMouseButtonDown(1))
        {
            if (_buildup != null) _buildup.BeginCharge(ActionType.Throw);
        }
        else if (IsCharging && Input.GetMouseButtonUp(1))
        {
            DoThrow();
        }
    }

    private void DoThrow()
    {
        if (_buildup == null || _thrownWrenchPrefab == null || _config == null) return;

        ChargeResult result = _buildup.ReleaseCharge();
        float chargeNorm = result.Normalized;

        Vector3 origin = CatchPoint;

        Vector3 toAim = _aimer.WorldAimPoint - origin;
        toAim.y = 0f;
        if (toAim.sqrMagnitude < 0.0001f) toAim = transform.forward;

        float maxDist = Mathf.Lerp(_config.minThrowDistance, _config.maxThrowDistance, chargeNorm);
        float dist = Mathf.Min(toAim.magnitude, maxDist);

        Vector3 target = origin + toAim.normalized * dist;
        target.y = _aimer.WorldAimPoint.y;

        GameObject go = Instantiate(_thrownWrenchPrefab, CatchPoint, Quaternion.identity);
        _airborne = go.GetComponent<ThrownWrench>();
        if (_airborne != null) _airborne.Launch(this, target, _config);
        else Destroy(go);

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ToolThrowReleased(target, chargeNorm));
    }

    /// <summary>Called by ThrownWrench when it has returned and been caught.</summary>
    public void OnCaught() => _airborne = null;
}

using UnityEngine;

/// <summary>
/// Marks a world object the player can grab and push/pull with E. The object is
/// kinematic by default so it can't be moved by physics collisions — only the
/// <see cref="PlayerCarryController"/> positions it while held. Implements
/// <see cref="IInteractionPromptProvider"/> so the HUD shows the prompt automatically.
/// </summary>
[RequireComponent(typeof(Rigidbody))]
[RequireComponent(typeof(Collider))]
public class Grabbable : MonoBehaviour, IInteractionPromptProvider
{
    [Tooltip("Display name shown in the prompt (e.g. 'Crate').")]
    [SerializeField] private string _displayName = "Crate";

    /// <summary>True while this object is being carried by the player.</summary>
    public bool IsHeld { get; private set; }

    private Rigidbody _rb;

    /// <summary>The Rigidbody on this object.</summary>
    public Rigidbody Body => _rb;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody>();
        // Always kinematic: the object is only moved by the carry controller,
        // never by physics collisions or forces.
        if (_rb != null) _rb.isKinematic = true;
    }

    /// <summary>Attach to the player — called by PlayerCarryController.</summary>
    public void OnGrab()
    {
        IsHeld = true;
    }

    /// <summary>Detach from the player — called by PlayerCarryController.</summary>
    public void OnRelease()
    {
        IsHeld = false;
    }

    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        if (IsHeld)
            prompt = new InteractionPrompt("E", "Release", transform, _displayName);
        else
            prompt = new InteractionPrompt("E", "Grab", transform, _displayName);
        return true;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Picks up the key-pickup <see cref="WorldItem"/> the player is aiming at when the pickup key is
/// pressed: grants its item(s) to the inventory and removes it from the world. Only non-auto-collect
/// items (e.g. the wrench) need this — auto-collect drops fly to the player on their own.
/// Reads the hovered item from <see cref="PlayerMouseAimer"/>; writes to <see cref="PlayerInventory"/>.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerPickupController : MonoBehaviour
{
    [SerializeField] private KeyCode _pickupKey = KeyCode.E;

    private PlayerMouseAimer _aimer;
    private PlayerCarryController _carry;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _carry = GetComponent<PlayerCarryController>();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(_pickupKey)) return;

        // Skip pickup while carrying an object
        if (_carry != null && _carry.IsCarrying) return;

        WorldItem item = _aimer.HoveredKeyPickup;
        if (item == null || item.Item == null) return;

        PlayerInventory inv = PlayerInventory.Instance;
        if (inv == null) return;

        int added = inv.TryAddItem(item.Item, item.Count);
        if (added <= 0) return;

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ItemPickedUp(item.Item, added));

        if (added >= item.Count) Destroy(item.gameObject);
        else                     item.Reduce(added);
    }
}

using System;
using UnityEngine;

/// <summary>
/// Owns the runtime inventory state (copied from <see cref="InventoryData"/> on Awake — the SO
/// itself is never mutated at runtime). Holds a flat array of <see cref="InventorySlot"/>s:
/// slot 0 is the wrench slot, slots 1..N are general item slots that stack identical items up to
/// <see cref="ItemDefinition.maxStack"/>. The slot count is data-driven and extendable.
///
/// Accepts any item kind (resources, future tools, etc.). Currency items never enter a slot —
/// they route to their <see cref="ItemDefinition.currencyTarget"/> at the collection site.
/// Handles hotkey input (1-4) to switch the active slot; raises events for the HUD.
///
/// Acts as the game's inventory manager: a singleton (<see cref="Instance"/>) so the HUD, pickup,
/// drop, magnets and the wrench controllers all reach inventory through one access point and
/// subscribe to its events — no FindObjectOfType, no per-system GetComponent. Single-player, so one
/// instance is assumed. Runs early (negative execution order) so <see cref="Instance"/> exists
/// before any subscriber's Awake/OnEnable.
///
/// Pure manager — holds no scene-position state and never touches the character controller, so it
/// lives on a dedicated manager GameObject (e.g. MANAGERS/INVENTORY), not on the Player. All users
/// reach it through <see cref="Instance"/>; nothing requires it to share the Player's GameObject.
/// </summary>
[DefaultExecutionOrder(-50)]
public class PlayerInventory : MonoBehaviour
{
    /// <summary>The active inventory manager. Set in Awake, cleared on destroy.</summary>
    public static PlayerInventory Instance { get; private set; }

    public const int WrenchSlot = 0;

    [SerializeField] private InventoryData _inventoryConfig;

    public event Action<int> OnSlotChanged;
    public event Action<int> OnActiveSlotChanged;

    private InventorySlot[] _runtimeSlots = Array.Empty<InventorySlot>();
    private int _activeSlot;

    // ── Public API ────────────────────────────────────────────────────────────

    public int SlotCount => _runtimeSlots.Length;

    public int ActiveSlotIndex
    {
        get => _activeSlot;
        private set
        {
            int clamped = Mathf.Clamp(value, 0, SlotCount - 1);
            if (_activeSlot == clamped) return;
            _activeSlot = clamped;
            OnActiveSlotChanged?.Invoke(_activeSlot);
        }
    }

    public InventorySlot ActiveSlot => GetSlot(_activeSlot);
    public ItemDefinition ActiveItem => ActiveSlot.item;

    /// <summary>ItemType of the currently selected slot, or None if it's empty.</summary>
    public ItemType ActiveItemType => ActiveItem != null ? ActiveItem.itemType : ItemType.None;

    /// <summary>True when no general slot is empty (can't accept a new item kind).</summary>
    public bool IsFull
    {
        get
        {
            for (int i = 1; i < _runtimeSlots.Length; i++)
                if (_runtimeSlots[i].IsEmpty) return false;
            return true;
        }
    }

    public InventorySlot GetSlot(int index)
    {
        if (index < 0 || index >= _runtimeSlots.Length) return InventorySlot.Empty;
        return _runtimeSlots[index];
    }

    /// <summary>True if any slot currently holds an item of the given type.</summary>
    public bool HasItem(ItemType type)
    {
        for (int i = 0; i < _runtimeSlots.Length; i++)
            if (!_runtimeSlots[i].IsEmpty && _runtimeSlots[i].item.itemType == type) return true;
        return false;
    }

    /// <summary>
    /// True if at least one unit of <paramref name="item"/> can be accepted right now
    /// (a matching non-full stack, or an empty slot). Used by world-item magnets to decide
    /// whether to fly to the player or stay on the ground.
    /// </summary>
    public bool HasRoomFor(ItemDefinition item)
    {
        if (item == null || item.isCurrency) return false;

        if (item.itemType == ItemType.Wrench)
            return GetSlot(WrenchSlot).IsEmpty;

        for (int i = 1; i < _runtimeSlots.Length; i++)
        {
            if (_runtimeSlots[i].IsEmpty) return true;
            if (_runtimeSlots[i].item == item && !_runtimeSlots[i].IsFull) return true;
        }
        return false;
    }

    /// <summary>
    /// Add up to <paramref name="count"/> of <paramref name="item"/>, stacking into matching
    /// slots first then filling empty ones. Returns how many were actually added (0 = no room).
    /// Currency items are rejected here (they belong on the currency counter, not a slot).
    /// </summary>
    public int TryAddItem(ItemDefinition item, int count = 1)
    {
        if (item == null || count <= 0 || item.isCurrency) return 0;

        if (item.itemType == ItemType.Wrench)
        {
            if (!GetSlot(WrenchSlot).IsEmpty) return 0;
            _runtimeSlots[WrenchSlot] = InventorySlot.Of(item, 1);
            OnSlotChanged?.Invoke(WrenchSlot);
            return 1;
        }

        int added = 0;

        // 1) Top up existing matching stacks.
        for (int i = 1; i < _runtimeSlots.Length && added < count; i++)
        {
            if (_runtimeSlots[i].item != item || _runtimeSlots[i].IsFull) continue;
            int take = Mathf.Min(_runtimeSlots[i].SpaceLeft, count - added);
            _runtimeSlots[i].count += take;
            added += take;
            OnSlotChanged?.Invoke(i);
        }

        // 2) Fill empty slots.
        for (int i = 1; i < _runtimeSlots.Length && added < count; i++)
        {
            if (!_runtimeSlots[i].IsEmpty) continue;
            int take = Mathf.Min(Mathf.Max(1, item.maxStack), count - added);
            _runtimeSlots[i] = InventorySlot.Of(item, take);
            added += take;
            OnSlotChanged?.Invoke(i);
        }

        return added;
    }

    /// <summary>Remove one unit from a slot; returns the item removed, or null if the slot was empty.</summary>
    public ItemDefinition RemoveOne(int index) => RemoveFromSlot(index, 1, out _);

    /// <summary>Remove the whole stack from a slot; returns the item and (via out) how many were removed.</summary>
    public ItemDefinition RemoveStack(int index, out int removed)
        => RemoveFromSlot(index, int.MaxValue, out removed);

    /// <summary>Remove up to <paramref name="count"/> units from a slot.</summary>
    public ItemDefinition RemoveFromSlot(int index, int count, out int removed)
    {
        removed = 0;
        if (index < 0 || index >= _runtimeSlots.Length || count <= 0) return null;

        InventorySlot slot = _runtimeSlots[index];
        if (slot.IsEmpty) return null;

        ItemDefinition item = slot.item;
        removed = Mathf.Min(count, slot.count);
        slot.count -= removed;
        _runtimeSlots[index] = slot.count <= 0 ? InventorySlot.Empty : slot;
        OnSlotChanged?.Invoke(index);
        return item;
    }

    // ── Signals (inbound) ───────────────────────────────────────────────────────
    // Readability aliases over the API above. Same pattern as ResourceManager.RaiseHit:
    // a gameplay system "signals" the inventory (e.g. a pickup collision), the inventory
    // mutates its slots, then broadcasts OnSlotChanged / OnActiveSlotChanged outward.
    // The store is the one place that owns slot state — these just read like events.

    /// <summary>Signal: an item pickup was requested (e.g. by a collision/magnet). Returns how
    /// many units actually entered the inventory. Forwards to <see cref="TryAddItem"/>.</summary>
    public int SignalPickup(ItemDefinition item, int count = 1) => TryAddItem(item, count);

    /// <summary>Signal: drop one unit from a slot. Returns the item removed, or null if empty.
    /// Forwards to <see cref="RemoveOne"/>.</summary>
    public ItemDefinition SignalDropOne(int slot) => RemoveOne(slot);

    /// <summary>Signal: drop a whole stack from a slot. Forwards to <see cref="RemoveStack"/>.</summary>
    public ItemDefinition SignalDropStack(int slot, out int removed) => RemoveStack(slot, out removed);

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
            Debug.LogWarning($"[PlayerInventory] Second instance on '{name}'; overriding the previous Instance.", this);
        Instance = this;

        int count = _inventoryConfig != null ? _inventoryConfig.Slots : 4;
        _runtimeSlots = new InventorySlot[count];
        for (int i = 0; i < count; i++)
        {
            ItemDefinition def = _inventoryConfig != null ? _inventoryConfig.GetDefaultSlot(i) : null;
            _runtimeSlots[i] = def != null ? InventorySlot.Of(def, 1) : InventorySlot.Empty;
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        ReadHotkeys();
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void ReadHotkeys()
    {
        if (Input.GetKeyDown(KeyCode.Alpha1))      ActiveSlotIndex = 0;
        else if (Input.GetKeyDown(KeyCode.Alpha2)) ActiveSlotIndex = 1;
        else if (Input.GetKeyDown(KeyCode.Alpha3)) ActiveSlotIndex = 2;
        else if (Input.GetKeyDown(KeyCode.Alpha4)) ActiveSlotIndex = 3;
    }
}

using UnityEngine;

/// <summary>
/// Aim indicator that shows the player's throw/swing direction.
/// The reticle billboards to match the camera-facing sprite, then rotates within
/// that plane using the screen-space angle to the mouse — so it visually orbits
/// the sprite's silhouette edge rather than sweeping on the world XZ ground plane.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerAimReticle : MonoBehaviour
{
    [SerializeField] private WrenchConfig _config;
    [Tooltip("Root pivot positioned at the player and yaw-rotated to the aim direction.")]
    [SerializeField] private Transform _reticleRoot;
    [Tooltip("Flat arrow whose length (local Y) scales with charge.")]
    [SerializeField] private Transform _arrow;
    [SerializeField] private SpriteRenderer _arrowSprite;

    [SerializeField] private Color _idleColor     = new Color(1f, 1f, 1f, 0.45f);
    [SerializeField] private Color _chargingColor = new Color(0.3f, 0.8f, 1f, 0.9f);
    [SerializeField] private Color _readyColor    = new Color(1f, 0.55f, 0.1f, 1f);
    [Tooltip("Arrow length multiplier at full charge.")]
    [SerializeField] private float _maxLengthMul = 2.2f;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private Camera _cam;
    private Vector3 _baseArrowScale = Vector3.one;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _cam        = Camera.main;
        if (_arrow != null) _baseArrowScale = _arrow.localScale;
    }

    private void LateUpdate()
    {
        // Aim reticle disabled — hide and bail.
        if (_reticleRoot != null) _reticleRoot.gameObject.SetActive(false);
    }

    // Wired late (controllers added after this component) — resolve lazily.
    private WrenchSwingController _swing;
    private WrenchThrowController _throw;
    private float SwingCharge()
    {
        if (_swing == null) _swing = GetComponent<WrenchSwingController>();
        return _swing != null && _swing.IsCharging ? _swing.ChargeNormalized : 0f;
    }
    private float ThrowCharge()
    {
        if (_throw == null) _throw = GetComponent<WrenchThrowController>();
        return _throw != null && _throw.IsCharging ? _throw.ChargeNormalized : 0f;
    }
}

using UnityEngine;

/// <summary>
/// Handles the scan interaction flow: holds F to scan a ScanTarget under the cursor.
/// Reads the current ScanTarget from <see cref="PlayerMouseAimer.HoverResult"/> each frame.
/// On key down: validates and calls <see cref="ScanTarget.Begin"/>.
/// While held: calls <see cref="ScanTarget.TickScan"/> and drains battery.
/// On key up or target lost: calls <see cref="ScanTarget.CancelScan"/>.
///
/// The <see cref="WorldInteractTagPresenter"/> already shows the scan progress text
/// by subscribing to <see cref="Flynn.Events.ScanProgressed"/> events.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerScanController : MonoBehaviour
{
    [Tooltip("Key to hold for scanning.")]
    [SerializeField] private KeyCode _scanKey = KeyCode.F;

    private PlayerMouseAimer _aimer;
    private RobotBattery _battery;
    private ScanTarget _activeTarget;
    private bool _keyHeld;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _battery = RobotBattery.Instance;
    }

    private void Update()
    {
        bool keyDown = Input.GetKeyDown(_scanKey);
        bool keyUp = Input.GetKeyUp(_scanKey);
        _keyHeld = Input.GetKey(_scanKey);

        var scanTarget = _aimer != null ? _aimer.HoverResult.ScanTarget : null;

        // Start scan on key down
        if (keyDown && scanTarget != null && scanTarget.CanStart())
        {
            _activeTarget = scanTarget;
            _activeTarget.Begin();
        }

        // Tick while held and target is valid
        if (_keyHeld && _activeTarget != null && _activeTarget.IsScanning)
        {
            // Verify target is still the one under cursor
            if (scanTarget != _activeTarget)
            {
                CancelActive();
                return;
            }

            // Check battery
            float costPerSecond = _activeTarget.Config != null
                ? _activeTarget.Config.batteryCostPerSecond : 0f;

            if (costPerSecond > 0f && _battery != null && !_battery.CanSpend(costPerSecond * Time.deltaTime))
            {
                CancelActive();
                return;
            }

            _activeTarget.TickScan(Time.deltaTime);

            if (_battery != null && costPerSecond > 0f)
                _battery.DrainOverTime(costPerSecond);
        }

        // Cancel on key up or target lost
        if (keyUp || (_activeTarget != null && !_activeTarget.IsScanning))
        {
            CancelActive();
        }
    }

    private void CancelActive()
    {
        if (_activeTarget != null && _activeTarget.IsScanning)
            _activeTarget.CancelScan();
        _activeTarget = null;
    }
}

using UnityEngine;

/// <summary>
/// Registers this object's Transform into a <see cref="PlayerAnchor"/> SO so runtime-spawned
/// world items can home in on the player without scene-wide lookups. Put on the Player root and
/// assign the same PlayerAnchor asset used by the dropped-item prefabs.
/// </summary>
[DisallowMultipleComponent]
public class PlayerAnchorRegistrar : MonoBehaviour
{
    [SerializeField] private PlayerAnchor _anchor;

    private void OnEnable()
    {
        if (_anchor != null) _anchor.Set(transform);
    }

    private void OnDisable()
    {
        if (_anchor != null) _anchor.Clear(transform);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Wrench grapple with swing physics. Hold Q to charge, release to fire.
/// A hook projectile travels from the player's visual center to the target,
/// then the player swings on the rope with pendulum physics (momentum preservation
/// on release). Grapples what the cursor is over (resolved by PlayerMouseAimer):
///   - RopeAnchor → swing the player around the anchor point
///   - RopePullable → reel the object toward the player
/// Blocked while on mud. Requires the wrench as the active item.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class RopeLassoController : MonoBehaviour
{
    [SerializeField] private RopeLassoConfig _config;
    [Tooltip("Rope visual. A child LineRenderer; enabled only while grappling.")]
    [SerializeField] private LineRenderer _ropeLine;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _controller;
    private TerrainStateAggregator _terrainState;
    private Rigidbody _rb;
    private PlayerCarryController _carry;

    // ── Charge ──────────────────────────────────────────────────────────────

    private float _chargeTimer;
    private bool _charging;

    // ── State machine ───────────────────────────────────────────────────────

    private enum GrappleState { Idle, Firing, Swinging, PullingObject }
    private GrappleState _state = GrappleState.Idle;

    // Firing state
    private Vector3 _fireStart;
    private Vector3 _fireTarget;
    private float _fireElapsed;

    // Swing state
    private Vector3 _anchorPoint;
    private float _ropeLength;
    private float _swingElapsed;

    // Pull state
    private Rigidbody _pullBody;
    private float _pullElapsed;

    // Rope visual
    private const int RopeSegments = 10;
    private Vector3[] _ropePoints;

    // Cached for end-event publishing
    private RopeAnchor _activeAnchor;
    private RopePullable _activePullable;

    // Actual world-space anchor (for visual), separate from the Y-projected _anchorPoint
    private Vector3 _anchorWorldPos;

    // ── Public API ──────────────────────────────────────────────────────────

    public bool IsCharging => _charging;
    public float ChargeNormalized => _config != null && _config.chargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.chargeTime) : 0f;
    public bool IsPulling => _state == GrappleState.Swinging || _state == GrappleState.PullingObject;
    public bool IsSwinging => _state == GrappleState.Swinging;

    /// <summary>
    /// Billboard visual centre — the rope leaves from the sprite's centre, not the feet.
    /// Uses the IPlayerVisual.VisualCenter which accounts for camera-tilt offset on
    /// the billboarded sprite.
    /// </summary>
    public Vector3 HandPoint => _animDriver != null ? _animDriver.VisualCenter : transform.position;

    // ── Awake ───────────────────────────────────────────────────────────────

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _controller = GetComponent<SolarpunkCharacterController>();
        _terrainState = GetComponent<TerrainStateAggregator>();
        _rb         = GetComponent<Rigidbody>();
        _carry      = GetComponent<PlayerCarryController>();

        _ropePoints = new Vector3[RopeSegments];

        if (_ropeLine != null)
        {
            _ropeLine.positionCount = RopeSegments;
            _ropeLine.enabled = false;
        }
    }

    // ── Update: input, charging, firing progress ────────────────────────────

    private void Update()
    {
        switch (_state)
        {
            case GrappleState.Idle:
                UpdateIdle();
                break;
            case GrappleState.Firing:
                UpdateFiring();
                break;
            case GrappleState.Swinging:
                UpdateSwingInput();
                break;
            case GrappleState.PullingObject:
                UpdatePullInput();
                break;
        }
    }

    private void UpdateIdle()
    {
        bool onMud = _terrainState != null
            ? _terrainState.CurrentTerrainState.BlocksRope
            : (_controller != null && !_controller.CanJump);
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !onMud
                      && (_carry == null || !_carry.IsCarrying);
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetKeyDown(KeyCode.Q))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetKey(KeyCode.Q))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetKeyUp(KeyCode.Q))
        {
            FireLasso();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void UpdateFiring()
    {
        _fireElapsed += Time.deltaTime;
        float fireDuration = _config != null ? _config.hookTravelTime : 0.12f;
        float t = Mathf.Clamp01(_fireElapsed / fireDuration);

        // Ease-out for a snappy travel feel
        float easedT = 1f - Mathf.Pow(1f - t, 3f);
        Vector3 hookPos = Vector3.Lerp(_fireStart, _fireTarget, easedT);

        // Draw extending rope from hand to hook tip (sag fades as hook approaches target)
        DrawRope(HandPoint, hookPos, slack: 0.4f * (1f - t));

        if (t >= 1f)
        {
            if (_activePullable != null)
                StartPullingObject();
            else
                StartSwinging();
        }
    }

    private void UpdateSwingInput()
    {
        // Release with Jump or Q
        if (Input.GetButtonDown("Jump") || Input.GetKeyDown(KeyCode.Q))
        {
            EndGrapple(preserveMomentum: true);
            return;
        }

        // Adjust rope length with scroll wheel
        if (_config != null)
        {
            float scroll = Input.mouseScrollDelta.y;
            if (scroll != 0f)
            {
                _ropeLength -= scroll * _config.ropeAdjustSpeed * Time.deltaTime;
                _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);
            }
        }
    }

    private void UpdatePullInput()
    {
        // Release pull with Q
        if (Input.GetKeyUp(KeyCode.Q))
            EndGrapple(preserveMomentum: false);
    }

    // ── Fire ────────────────────────────────────────────────────────────────

    private void FireLasso()
    {
        if (_config == null) return;

        RopeAnchor anchor = _aimer.HoveredAnchor;
        RopePullable pullable = _aimer.HoveredPullable;
        if (anchor == null && pullable == null) return;

        Vector3 grapplePoint = _aimer.HoveredGrapplePoint;
        float dist = Vector3.Distance(HandPoint, grapplePoint);
        if (dist < _config.minRange || dist > _config.maxRange) return;

        // Battery check
        var battery = RobotBattery.Instance;
        float grappleCost = battery != null && battery.Settings != null
            ? battery.Settings.grappleCost : 0f;
        if (battery != null && !battery.CanSpend(grappleCost)) return;
        if (battery != null && grappleCost > 0f) battery.Spend(grappleCost);

        // Cache targets for events
        _activeAnchor = anchor;
        _activePullable = pullable;

        // Start firing
        _state = GrappleState.Firing;
        _fireStart = HandPoint;
        _fireTarget = grapplePoint;
        _fireElapsed = 0f;

        // Face the target
        if (_animDriver != null) _animDriver.FaceWorldDirection(grapplePoint - transform.position);

        // Publish start event immediately
        if (GameEventBus.Instance != null)
        {
            if (pullable != null)
                GameEventBus.Instance.Publish(new RopePullStarted(pullable));
            else if (anchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleStarted(anchor));
        }
    }

    // ── State transitions ───────────────────────────────────────────────────

    private void StartSwinging()
    {
        _state = GrappleState.Swinging;
        _swingElapsed = 0f;

        // 2.5D: project the anchor onto the player's Y so the tether is horizontal-only.
        // The rope constrains on the XZ plane; Y is entirely gravity/jump controlled.
        _anchorPoint = new Vector3(_fireTarget.x, _rb.position.y, _fireTarget.z);
        _anchorWorldPos = _fireTarget;

        // Rope length = initial horizontal distance to anchor
        Vector3 toAnchorXZ = _anchorPoint - _rb.position;
        toAnchorXZ.y = 0f;
        _ropeLength = toAnchorXZ.magnitude;
        if (_config != null)
            _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);

        // Snap impulse toward anchor on XZ only (no vertical yank)
        if (_config != null && _config.snapForce > 0f && _rb != null)
        {
            Vector3 toAnchor = (_anchorPoint - _rb.position);
            toAnchor.y = 0f;
            if (toAnchor.sqrMagnitude > 0.01f)
                _rb.AddForce(toAnchor.normalized * _config.snapForce, ForceMode.Impulse);
        }

        // Suppress character controller so it doesn't fight the swing
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void StartPullingObject()
    {
        _state = GrappleState.PullingObject;
        _pullBody = _activePullable != null ? _activePullable.Body : null;
        _pullElapsed = 0f;

        if (_pullBody == null) { EndGrapple(false); return; }
    }

    // ── FixedUpdate: swing & pull physics ────────────────────────────────────

    private void FixedUpdate()
    {
        switch (_state)
        {
            case GrappleState.Swinging:
                UpdateSwingPhysics();
                break;
            case GrappleState.PullingObject:
                UpdatePullPhysics();
                break;
        }
    }

    private void UpdateSwingPhysics()
    {
        if (_rb == null) { EndGrapple(false); return; }

        _swingElapsed += Time.fixedDeltaTime;

        // Safety timeout
        if (_config != null && _swingElapsed >= _config.pullTimeout)
        {
            EndGrapple(true);
            return;
        }

        // Battery drain while swinging
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(true); return; }
        }

        // 2.5D: re-project anchor to player's Y each step so the tether stays horizontal
        // even as the player rises/falls from gravity and jumps.
        _anchorPoint = new Vector3(_anchorPoint.x, _rb.position.y, _anchorPoint.z);

        // Swing input: WASD adds tangential force on the XZ plane to pump the swing
        Vector3 inputDir = new Vector3(
            Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical")).normalized;
        if (inputDir.sqrMagnitude > 0.01f)
        {
            Vector3 toAnchorXZ = (_anchorPoint - _rb.position);
            toAnchorXZ.y = 0f;
            if (toAnchorXZ.sqrMagnitude > 0.001f)
            {
                toAnchorXZ.Normalize();
                // Tangent on XZ: perpendicular to the rope direction
                Vector3 tangent = inputDir - Vector3.Project(inputDir, toAnchorXZ);
                tangent.y = 0f;
                if (tangent.sqrMagnitude > 0.001f)
                {
                    tangent.Normalize();
                    float swingForce = _config != null ? _config.swingForce : 30f;
                    _rb.AddForce(tangent * swingForce, ForceMode.Acceleration);
                }
            }
        }

        // 2.5D: enforce rope length constraint on the XZ plane only.
        // Y is untouched — gravity and jumps work normally while tethered.
        Vector3 toAnchorVec = _anchorPoint - _rb.position;
        toAnchorVec.y = 0f;
        float currentDistXZ = toAnchorVec.magnitude;

        if (currentDistXZ > _ropeLength && currentDistXZ > 0.001f)
        {
            Vector3 dirXZ = toAnchorVec.normalized;

            // Correct XZ position to stay on the horizontal rope circle
            Vector3 corrected = _rb.position;
            corrected.x = _anchorPoint.x - dirXZ.x * _ropeLength;
            corrected.z = _anchorPoint.z - dirXZ.z * _ropeLength;
            _rb.position = corrected;

            // Remove outward radial XZ velocity (keep tangential + all Y velocity)
            Vector3 outwardXZ = new Vector3(-dirXZ.x, 0f, -dirXZ.z);
            float vOut = Vector3.Dot(new Vector3(_rb.velocity.x, 0f, _rb.velocity.z), outwardXZ);
            if (vOut > 0f)
            {
                Vector3 correction = outwardXZ * vOut;
                _rb.velocity -= correction;
            }

            // Cap XZ swing speed only (Y is free)
            Vector3 velXZ = new Vector3(_rb.velocity.x, 0f, _rb.velocity.z);
            if (_config != null && velXZ.magnitude > _config.maxSwingSpeed)
            {
                velXZ = velXZ.normalized * _config.maxSwingSpeed;
                _rb.velocity = new Vector3(velXZ.x, _rb.velocity.y, velXZ.z);
            }
        }

        // Suppress character controller each step (it auto-resets to 1)
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void UpdatePullPhysics()
    {
        if (_pullBody == null) { EndGrapple(false); return; }

        _pullElapsed += Time.fixedDeltaTime;
        if (_config != null && _pullElapsed >= _config.pullTimeout)
        {
            EndGrapple(false);
            return;
        }

        // Battery drain while pulling
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(false); return; }
        }

        // Pull the object toward the player's hand
        Vector3 target = HandPoint;
        Vector3 to = target - _pullBody.position;

        float stopRadius = _config != null ? _config.stopRadius : 0.8f;
        if (to.magnitude <= stopRadius)
        {
            EndGrapple(false);
            return;
        }

        float pullForce = _config != null ? _config.pullForce : 55f;
        float maxPullSpeed = _config != null ? _config.maxPullSpeed : 14f;

        _pullBody.AddForce(to.normalized * pullForce, ForceMode.Acceleration);
        if (_pullBody.velocity.magnitude > maxPullSpeed)
            _pullBody.velocity = _pullBody.velocity.normalized * maxPullSpeed;
    }

    // ── End grapple ─────────────────────────────────────────────────────────

    private void EndGrapple(bool preserveMomentum)
    {
        // Publish end events
        if (GameEventBus.Instance != null)
        {
            if (_activeAnchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleEnded(_activeAnchor));
            if (_activePullable != null)
                GameEventBus.Instance.Publish(new RopePullEnded(_activePullable));
        }

        // 2.5D: on swing release, just let momentum carry — no forced vertical boost.
        // The player keeps their current XZ swing velocity (tangential) plus whatever
        // Y velocity they have from gravity/jumps.

        // Restore character controller
        if (_controller != null) _controller.SteeringControl = 1f;

        _state = GrappleState.Idle;
        _pullBody = null;
        _swingElapsed = 0f;
        _pullElapsed = 0f;
        _activeAnchor = null;
        _activePullable = null;
    }

    // ── LateUpdate: rope visual ─────────────────────────────────────────────

    private void LateUpdate()
    {
        if (_ropeLine == null) return;

        switch (_state)
        {
            case GrappleState.Swinging:
                // Taut rope from hand to the actual world anchor (not Y-projected)
                DrawRope(HandPoint, _anchorWorldPos, slack: 0.02f);
                break;

            case GrappleState.PullingObject:
                if (_pullBody != null)
                    DrawRope(HandPoint, _pullBody.position, slack: 0.08f);
                else
                    _ropeLine.enabled = false;
                break;

            case GrappleState.Firing:
                // Handled in UpdateFiring
                break;

            default:
                _ropeLine.enabled = false;
                break;
        }
    }

    // ── Rope drawing with sag ───────────────────────────────────────────────

    /// <summary>
    /// Draw the rope from start to end with a parabolic sag.
    /// slack=0 → taut straight line; slack=0.3 → visible droop.
    /// </summary>
    private void DrawRope(Vector3 start, Vector3 end, float slack)
    {
        if (_ropeLine == null) return;

        _ropeLine.enabled = true;

        float dist = Vector3.Distance(start, end);

        for (int i = 0; i < RopeSegments; i++)
        {
            float t = (float)i / (RopeSegments - 1);
            Vector3 point = Vector3.Lerp(start, end, t);

            // Parabolic sag: max at middle, zero at ends
            float sagAmount = slack * 4f * t * (1f - t) * dist;
            point += Vector3.down * sagAmount;

            _ropePoints[i] = point;
        }

        _ropeLine.SetPositions(_ropePoints);
    }
}

