    public float swingCost = 2f;
    [Tooltip("Battery cost per wrench throw.")]
    public float throwCost = 5f;
    [Tooltip("Battery cost to start a grapple (flat).")]
    public float grappleCost = 8f;
    [Tooltip("Battery cost per second while actively pulling with the rope.")]
    public float pullCostPerSecond = 3f;
    [Tooltip("Battery cost per second while scanning (future).")]
    public float scanCostPerSecond = 5f;
    [Tooltip("Battery cost per second while restoring (future).")]
    public float restoreCostPerSecond = 5f;

    [Header("Thresholds")]
    [Tooltip("Battery level (0-100) below which the BatteryLow event fires.")]
    public int lowBatteryThreshold = 20;

    [Header("Debug")]
    [Tooltip("When true, CanSpend always returns true and Spend is a no-op. For sandbox testing.")]
    public bool infiniteBatteryDebug = false;
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Robot energy system. Owns a 0–100 <see cref="IntVariable"/> battery and drains it
/// both passively (over time) and actively (from gameplay actions via <see cref="BatterySettings"/>).
/// The HUD reads the battery purely through <see cref="IntVariable.OnChanged"/>.
///
/// Supports a configurable <see cref="BatterySettings"/> SO for action costs and an
/// <c>infiniteBatteryDebug</c> toggle for sandbox testing without battery interference.
/// </summary>
[DefaultExecutionOrder(-40)]
public class RobotBattery : MonoBehaviour
{
    public const int Min = 0;
    public const int Max = 100;

    public static RobotBattery Instance { get; private set; }

    [Tooltip("The shared 0–100 battery value the HUD displays. Assign the same asset on PlayerHudPanel.")]
    [SerializeField] private IntVariable _battery;

    [Tooltip("Battery settings: action costs, passive drain, debug mode.")]
    [SerializeField] private BatterySettings _settings;

    [SerializeField, Range(Min, Max)] private int _startCharge = 100;

    [Tooltip("Passive drain in battery points per second. Overridden by BatterySettings if assigned.")]
    [SerializeField] private float _drainPerSecond = 1f;

    [SerializeField] private bool _autoDrain = true;

    private float _accum;

    // ── API ──────────────────────────────────────────────────────────────────

    public int Charge => _battery != null ? _battery.Value : 0;
    public bool IsEmpty => Charge <= Min;
    public bool IsFull  => Charge >= Max;

    /// <summary>Whether infinite battery debug mode is active.</summary>
    public bool InfiniteDebug => _settings != null && _settings.infiniteBatteryDebug;

    /// <summary>Access to battery settings for cost lookups (read-only).</summary>
    public BatterySettings Settings => _settings;

    /// <summary>
    /// Can the battery afford this cost? Returns true if infinite debug is on,
    /// or if there's enough charge (as a float, so partial charges are possible).
    /// </summary>
    public bool CanSpend(float cost)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return true;
        return Charge >= cost;
    }

    /// <summary>
    /// Spend a float amount of battery (for action costs). No-op in infinite debug mode.
    /// Publishes <see cref="BatteryChanged"/> and threshold events.
    /// </summary>
    public void Spend(float cost)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return;
        if (cost <= 0f) return;
        _accum -= cost;
        FlushAccum();
    }

    /// <summary>Drain over time (continuous actions like pulling/scanning).</summary>
    public void DrainOverTime(float costPerSecond)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return;
        _accum -= costPerSecond * Time.deltaTime;
        FlushAccum();
    }

    /// <summary>Add charge (negative to drain). Clamped to 0–100; notifies via the IntVariable.</summary>
    public void AddCharge(int amount) => SetCharge(Charge + amount);

    /// <summary>Drain charge by a positive amount.</summary>
    public void Drain(int amount) => SetCharge(Charge - Mathf.Abs(amount));

    public void SetCharge(int value)
    {
        if (_battery == null) return;
        int prev = Charge;
        _battery.Value = Mathf.Clamp(value, Min, Max);
        int current = Charge;

        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Publish(new BatteryChanged(current, Max));
            if (current <= Min && prev > Min)
                GameEventBus.Instance.Publish(new BatteryEmpty());
            else if (current <= LowThreshold && prev > LowThreshold)
                GameEventBus.Instance.Publish(new BatteryLow(current, (float)current / Max));
        }
    }

    public void SetAutoDrain(bool on) => _autoDrain = on;

    private int LowThreshold => _settings != null ? _settings.lowBatteryThreshold : 20;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[RobotBattery] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        SetCharge(_startCharge);
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (!_autoDrain || _battery == null || IsEmpty) return;

        float drainRate = _settings != null && _settings.enablePassiveDrain
            ? _settings.passiveDrainPerSecond
            : _drainPerSecond;

        if (drainRate <= 0f) return;

        _accum -= drainRate * Time.deltaTime;
        FlushAccum();
    }

    /// <summary>Flush accumulated fractional drain to the integer battery value.</summary>
    private void FlushAccum()
    {
        if (_accum >= 0f) return;
        int whole = Mathf.FloorToInt(-_accum);
        if (whole <= 0) return;
        _accum += whole;
        Drain(whole);
    }
}

using UnityEngine;

/// <summary>
/// The physical material of a meleeable surface, used to decide which tool the
/// wrench multitool "transforms" into when swung at it (and so which attack
/// animation plays). Air (nothing hovered) is handled by the swing controller,
/// not represented here.
/// </summary>
public enum SurfaceMaterial
{
    Wood,
    Metal,
    Rock,
}

/// <summary>
/// Marks any object as a meleeable surface with a <see cref="SurfaceMaterial"/>.
/// Drop on crates, walls, etc. so the wrench reads them as wood/metal/rock and
/// swings the matching tool. <see cref="ResourceNode"/> does NOT need this — it
/// derives its own tool from its required-tool config; this is for non-resource
/// props that still want the tool-swap read.
///
/// AttackAnimIndex maps SurfaceMaterial → Animator AttackIndex (1-4), matching
/// <see cref="ResourceNode.AttackAnimIndex"/>: Pick = 1 | Axe = 2 | Hammer = 3 | Wrench = 4.
/// </summary>
public class HittableSurface : MonoBehaviour
{
    [Tooltip("Physical material of this surface. Decides which tool the wrench swings: Wood→Axe, Metal→Hammer, Rock→Pick.")]
    [SerializeField] private SurfaceMaterial _material = SurfaceMaterial.Wood;

    public SurfaceMaterial Material => _material;

    /// <summary>Animator AttackIndex for this surface's matching tool.</summary>
    public int AttackAnimIndex => _material switch
    {
        SurfaceMaterial.Wood  => 2, // axe
        SurfaceMaterial.Metal => 3, // hammer
        SurfaceMaterial.Rock  => 1, // pick
        _                     => 4, // wrench (shouldn't hit; defensive)
    };
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Manages the hold-to-charge power buildup for swing and throw actions.
/// Controllers call <see cref="BeginCharge"/> on mouse-down and <see cref="ReleaseCharge"/>
/// on mouse-up. The manager drives the charge timer each frame, publishes events for
/// the HUD bar, and returns a <see cref="ChargeResult"/> with scaled damage and battery cost.
///
/// Battery cost and damage scale linearly between light and heavy values in
/// <see cref="PowerBuildupSettings"/>. A "perfect zone" window at the right side
/// of the bar gives a satisfying timing indicator.
/// </summary>
[DefaultExecutionOrder(-35)]
public class PowerBuildupManager : MonoBehaviour
{
    public static PowerBuildupManager Instance { get; private set; }

    [SerializeField] private PowerBuildupSettings _settings;

    private enum State { Idle, Charging }

    private State _state = State.Idle;
    private ActionType _currentType;
    private float _chargeTimer;
    private bool _peaked; // true once charge hits 1.0 (used for decay)

    // ── Public API ──────────────────────────────────────────────────────────

    public bool IsCharging => _state == State.Charging;
    public float ChargeNormalized => _state != State.Charging ? 0f : NormalizedCharge();
    public ActionType CurrentType => _currentType;

    /// <summary>Begin charging for the given action type.</summary>
    public void BeginCharge(ActionType type)
    {
        if (_state == State.Charging) return;

        // Check minimum battery cost
        var battery = RobotBattery.Instance;
        float minCost = type == ActionType.Swing
            ? (_settings != null ? _settings.lightSwingBatteryCost : 2f)
            : (_settings != null ? _settings.lightThrowBatteryCost : 5f);
        if (battery != null && !battery.CanSpend(minCost)) return;

        _state = State.Charging;
        _currentType = type;
        _chargeTimer = 0f;
        _peaked = false;

        Publish(new PowerBuildupStarted(type));
    }

    /// <summary>Release the charge and get the result.</summary>
    public ChargeResult ReleaseCharge()
    {
        if (_state != State.Charging) return default;

        float norm = NormalizedCharge();
        bool isPerfect = _settings != null
            && norm >= _settings.perfectZoneStart
            && norm <= _settings.perfectZoneEnd;

        int damage;
        float batteryCost;
        float animSpeed;

        if (_currentType == ActionType.Swing)
        {
            damage = _settings != null
                ? Mathf.RoundToInt(Mathf.Lerp(_settings.lightSwingDamage, _settings.heavySwingDamage, norm))
                : 1;
            batteryCost = _settings != null
                ? Mathf.Lerp(_settings.lightSwingBatteryCost, _settings.heavySwingBatteryCost, norm)
                : 2f;
            animSpeed = _settings != null
                ? Mathf.Lerp(_settings.lightSwingAnimSpeed, _settings.heavySwingAnimSpeed, norm)
                : 1f;
        }
        else
        {
            damage = _settings != null
                ? Mathf.RoundToInt(Mathf.Lerp(_settings.lightThrowDamage, _settings.heavyThrowDamage, norm))
                : 1;
            batteryCost = _settings != null
                ? Mathf.Lerp(_settings.lightThrowBatteryCost, _settings.heavyThrowBatteryCost, norm)
                : 5f;
            animSpeed = 1f;
        }

        var result = new ChargeResult(norm, isPerfect, damage, batteryCost, animSpeed, _currentType);

        // Spend battery
        var battery = RobotBattery.Instance;
        if (battery != null && batteryCost > 0f) battery.Spend(batteryCost);

        Publish(new PowerBuildupReleased(norm, isPerfect, damage, batteryCost, _currentType));

        _state = State.Idle;
        _chargeTimer = 0f;
        _peaked = false;

        return result;
    }

    /// <summary>Cancel without releasing (e.g. unequipped wrench mid-charge).</summary>
    public void CancelCharge()
    {
        if (_state != State.Charging) return;
        _state = State.Idle;
        _chargeTimer = 0f;
        _peaked = false;
        Publish(new PowerBuildupReleased(0f, false, 0, 0f, _currentType));
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[PowerBuildupManager] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (_state != State.Charging) return;

        float maxTime = _settings != null ? _settings.maxChargeTime : 2f;

        if (!_peaked)
        {
            _chargeTimer += Time.deltaTime;
            if (_chargeTimer >= maxTime)
            {
                _chargeTimer = maxTime;
                _peaked = true;
            }
        }
        else if (_settings != null && _settings.decayRate > 0f)
        {
            _chargeTimer -= _settings.decayRate * Time.deltaTime;
            if (_chargeTimer <= 0f) _chargeTimer = 0f;
        }

        float norm = NormalizedCharge();
        bool inPerfect = _settings != null
            && norm >= _settings.perfectZoneStart
            && norm <= _settings.perfectZoneEnd;

        Publish(new PowerBuildupChanged(norm, inPerfect));
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private float NormalizedCharge()
    {
        float maxTime = _settings != null ? _settings.maxChargeTime : 2f;
        return maxTime > 0f ? Mathf.Clamp01(_chargeTimer / maxTime) : 0f;
    }

    private static void Publish<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

/// <summary>
/// Result of a released charge. Controllers use this to determine damage,
/// battery cost, animation speed, and throw distance scaling.
/// </summary>
public struct ChargeResult
{
    public readonly float Normalized;
    public readonly bool IsPerfect;
    public readonly int Damage;
    public readonly float BatteryCost;
    public readonly float AnimSpeed;
    public readonly ActionType Type;

    public ChargeResult(float normalized, bool isPerfect, int damage, float batteryCost, float animSpeed, ActionType type)
    {
        Normalized = normalized;
        IsPerfect = isPerfect;
        Damage = damage;
        BatteryCost = batteryCost;
        AnimSpeed = animSpeed;
        Type = type;
    }
}

using UnityEngine;

/// <summary>
/// Configurable power buildup system. Designers tune charge timing, the "perfect zone"
/// window, and how charge scales battery cost and damage for swings and throws.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Player/Power Buildup Settings", fileName = "PowerBuildupSettings")]
public class PowerBuildupSettings : ScriptableObject
{
    [Header("Charge Timing")]
    [Tooltip("Seconds to fill the bar from 0 to 1.")]
    public float maxChargeTime = 2.0f;

    [Tooltip("Optional: rate at which charge decays per second after the bar is full (0 = no decay).")]
    public float decayRate = 0f;

    [Header("Perfect Zone")]
    [Tooltip("Charge fraction where the perfect zone starts (right side of bar).")]
    [Range(0f, 1f)] public float perfectZoneStart = 0.75f;
    [Tooltip("Charge fraction where the perfect zone ends.")]
    [Range(0f, 1f)] public float perfectZoneEnd = 0.90f;

    [Header("Swing Battery Cost (scaled by charge)")]
    public float lightSwingBatteryCost = 2f;
    public float heavySwingBatteryCost = 8f;

    [Header("Throw Battery Cost (scaled by charge)")]
    public float lightThrowBatteryCost = 5f;
    public float heavyThrowBatteryCost = 12f;

    [Header("Swing Damage (scaled by charge)")]
    [Min(1)] public int lightSwingDamage = 1;
    [Min(1)] public int heavySwingDamage = 3;

    [Header("Throw Damage (scaled by charge)")]
    [Min(1)] public int lightThrowDamage = 1;
    [Min(1)] public int heavyThrowDamage = 3;

    [Header("Swing Animation")]
    [Min(0.1f)] public float lightSwingAnimSpeed = 1.0f;
    [Min(0.1f)] public float heavySwingAnimSpeed = 2.5f;
}
